const STORAGE_KEY='range-plan-presenter-v1';
const APP_VERSION='2.0.1';
const TOKEN_KEY='range-operation-team-token';
const USER_KEY='range-operation-team-user';
const STATUS=['Upcoming','InProgress','Completed','AtRisk','Delayed','OnHold'];
const STATUS_LABEL={Upcoming:'Upcoming',InProgress:'In Progress',Completed:'Completed',AtRisk:'At Risk',Delayed:'Delayed',OnHold:'On Hold',OnTrack:'On Track'};
const COLORS=['#3157d5','#7357ff','#00a3ff','#1f9d68','#d18b12','#d44a55','#7b5de4','#1685a9','#a755b7','#526274','#e46c3c'];
const DATASET_VERSION=20260810;
const seed=window.RANGE_SEED;
function dateOffset(n){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function resp(unit,pic=''){return {unit,pic}}
function step(text,dueOffset,status='NotStarted'){return{id:uid(),text,due:dateOffset(dueOffset),status}}
function activity(id,task,subTask,key,s,e,status,responsibilities,nextSteps=[]){return{id,task,subTask,key,plannedStart:dateOffset(s),plannedEnd:dateOffset(e),actualStart:status==='Completed'?dateOffset(s):'',actualEnd:status==='Completed'?dateOffset(e):'',status,responsibilities,nextSteps}}
function uid(){return Math.random().toString(36).slice(2,10)+Date.now().toString(36)}
function clone(x){return JSON.parse(JSON.stringify(x))}
let state=load(); let page='dashboard'; let presentIndex=0; let presentProjectIds=[]; let ganttMode='Week'; let ganttZoom=100; let detailGanttGroup='taskSubTask'; let dashboardTimeMode=state.dashboard?.timeMode||'Week'; let dashboardZoom=Number(state.dashboard?.zoom||100); let dashboardFilter={search:'',eventType:'All',status:'All',section:'All',subSection:'All',owner:'All'}; let dashboardSort='liveAsc'; let dashboardGroupMode='section'; let dashboardSectionField=state.dashboard?.groupBy||'custom'; let dashboardSubSectionField=state.dashboard?.subGroupBy||'none'; let dashboardTimelineGroup=state.dashboard?.timelineGroup||'subtask'; let projectListSearch=''; let projectListSort='projectAsc'; let serverRevision=Number(state.settings?.serverRevision||0); let teamRole='local'; let syncTimer=null; let isSyncing=false; let activeSavedView='';
function migrateState(x){
  if(!x||!x.projects||!x.masters)return clone(seed);
  const current=Number(x.dataVersion||0);
  if(current<DATASET_VERSION){
    x.projects=(x.projects||[]).filter(p=>p.id!=='p-demo');
    const existing=new Set(x.projects.map(p=>p.id));
    seed.projects.forEach(p=>{if(!existing.has(p.id))x.projects.push(clone(p))});
    x.masters=x.masters||{tasks:[],units:[],milestones:[]};
    x.masters.tasks=x.masters.tasks||[]; seed.masters.tasks.forEach(v=>{if(!x.masters.tasks.includes(v))x.masters.tasks.push(v)});
    x.masters.units=x.masters.units||[]; seed.masters.units.forEach(v=>{if(!x.masters.units.includes(v))x.masters.units.push(v)});
    x.masters.milestones=x.masters.milestones||[];
    const mk=new Set(x.masters.milestones.map(m=>m.key)); seed.masters.milestones.forEach(m=>{if(!mk.has(m.key))x.masters.milestones.push(clone(m))});
    x.settings={...(x.settings||{}),appName:'Range Operation Platform'};
    x.version=2;x.dataVersion=DATASET_VERSION;
    if(!x.selectedProjectId||!x.projects.some(p=>p.id===x.selectedProjectId))x.selectedProjectId=x.projects[0]?.id||'';
    localStorage.setItem(STORAGE_KEY,JSON.stringify(x));
  }
  x.dashboard=x.dashboard||{};
  x.dashboard.sections=Array.isArray(x.dashboard.sections)?x.dashboard.sections:[];
  x.dashboard.groupBy=x.dashboard.groupBy||'custom';
  x.dashboard.subGroupBy=x.dashboard.subGroupBy||'none';
  x.dashboard.timelineGroup=x.dashboard.timelineGroup||'subtask';
  if(!x.dashboard.phasingViewV1){x.dashboard.timelineGroup='subtask';x.dashboard.phasingViewV1=true;localStorage.setItem(STORAGE_KEY,JSON.stringify(x));}
  x.settings={...(x.settings||{}),appName:'Range Operation Platform',schemaVersion:3,teamSync:!!x.settings?.teamSync,serverRevision:Number(x.settings?.serverRevision||0)};
  x.dashboard.savedViews=Array.isArray(x.dashboard.savedViews)?x.dashboard.savedViews:[];
  x.dashboard.collapsedProjects=Array.isArray(x.dashboard.collapsedProjects)?x.dashboard.collapsedProjects:[];
  x.dashboard.collapsedTasks=Array.isArray(x.dashboard.collapsedTasks)?x.dashboard.collapsedTasks:[];
  const liveKeys=/live|go$|implementation|relaunch|target live/i;
  x.masters.milestones=(x.masters.milestones||[]).map(m=>({...m,kind:m.kind||'Milestone',isLiveDefault:m.isLiveDefault===true||liveKeys.test(String(m.key||'')+' '+String(m.name||''))}));
  x.projects=(x.projects||[]).map(p=>({
    ...p,
    dashboardSectionId:p.dashboardSectionId||'',showOnDashboard:p.showOnDashboard!==false,
    progressMode:p.progressMode||'calculated',reportedProgress:Number.isFinite(Number(p.reportedProgress))?Number(p.reportedProgress):null,
    capacityHours:Number.isFinite(Number(p.capacityHours))?Number(p.capacityHours):0,
    criticality:p.criticality||'Normal',weeklyUpdate:p.weeklyUpdate||p.summary||'',
    activities:(p.activities||[]).map(a=>({...a,activityType:a.activityType||((a.plannedStart&&a.plannedEnd&&a.plannedStart===a.plannedEnd)?'Milestone':'Activity'),weight:Number(a.weight||1),isPrimaryLive:a.isPrimaryLive===true,isCriticalPath:a.isCriticalPath===true}))
  }));
  return x;
}
function load(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY));if(x&&x.projects&&x.masters)return migrateState(x)}catch{} const x=clone(seed);x.dashboard={sections:[],groupBy:'custom',subGroupBy:'none',timelineGroup:'subtask',phasingViewV1:true,savedViews:[],collapsedProjects:[]};x.settings={...(x.settings||{}),schemaVersion:3,teamSync:false,serverRevision:0};return migrateState(x)}
function save(){state.settings=state.settings||{};state.settings.serverRevision=serverRevision;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(state.settings.teamSync)queueTeamSync();}
function teamToken(){return sessionStorage.getItem(TOKEN_KEY)||''}
function teamUser(){return localStorage.getItem(USER_KEY)||'User'}
function teamHeaders(json=false){const h={};const t=teamToken();if(t)h.Authorization='Bearer '+t;h['X-Range-User']=teamUser();if(json)h['Content-Type']='application/json';return h}
function updateSyncBadge(mode='local',text='Local'){const el=document.getElementById('syncStatus');if(!el)return;el.className='sync-status '+mode;el.textContent=text}
function queueTeamSync(){if(isSyncing)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncServer(true),700)}
async function checkTeamSession(){try{const r=await fetch('/api/session',{headers:teamHeaders()});const x=await r.json();teamRole=x.role||'none';if(state.settings?.teamSync)updateSyncBadge(teamRole==='viewer'?'viewer':'synced',teamRole==='none'?'Auth needed':`Team · ${teamRole}`);else updateSyncBadge('local','Local')}catch{teamRole='local';updateSyncBadge('local','Local')}}
async function loadServerState({silent=false}={}){try{updateSyncBadge('syncing','Loading…');const r=await fetch('/api/state',{headers:teamHeaders()});const x=await r.json();if(!r.ok)throw new Error(x.error||'Load failed');teamRole=x.role||teamRole;serverRevision=Number(x.revision||0);if(x.state&&x.state.projects){state=migrateState(x.state);state.settings=state.settings||{};state.settings.serverRevision=serverRevision;state.settings.teamSync=true;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));dashboardSectionField=state.dashboard?.groupBy||'custom';dashboardSubSectionField=state.dashboard?.subGroupBy||'none';dashboardTimelineGroup=state.dashboard?.timelineGroup||'subtask';dashboardTimeMode=state.dashboard?.timeMode||'Week';dashboardZoom=Number(state.dashboard?.zoom||100);render()}updateSyncBadge(teamRole==='viewer'?'viewer':'synced',`Synced r${serverRevision}`);return true}catch(e){updateSyncBadge('conflict','Sync error');if(!silent)alert('Team sync: '+e.message);return false}}
async function syncServer(silent=false){if(isSyncing)return;try{isSyncing=true;updateSyncBadge('syncing','Syncing…');const payload={state,baseRevision:serverRevision,user:teamUser()};const res=await fetch('/api/state',{method:'PUT',headers:teamHeaders(true),body:JSON.stringify(payload)});const x=await res.json();if(res.status===409){updateSyncBadge('conflict',`Conflict r${x.currentRevision}`);if(!silent&&confirm('A newer team revision exists. Load the latest team version now?'))await loadServerState();return}if(!res.ok)throw new Error(x.error||'Save failed');serverRevision=Number(x.revision||serverRevision);state.settings=state.settings||{};state.settings.serverRevision=serverRevision;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));updateSyncBadge('synced',`Synced r${serverRevision}`);if(!silent)alert(`Team state saved · revision ${serverRevision}`)}catch(e){updateSyncBadge('conflict','Sync error');if(!silent)alert('Team sync failed: '+e.message)}finally{isSyncing=false}}
function setTeamSync(enabled){state.settings=state.settings||{};state.settings.teamSync=!!enabled;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(enabled)loadServerState();else{updateSyncBadge('local','Local');render()}}
function setTeamIdentity(){const name=(document.getElementById('teamUserName')?.value||'').trim()||'User';const token=(document.getElementById('teamToken')?.value||'').trim();localStorage.setItem(USER_KEY,name);if(token)sessionStorage.setItem(TOKEN_KEY,token);else sessionStorage.removeItem(TOKEN_KEY);checkTeamSession().then(()=>openTeamCenter())}
async function openTeamCenter(){let history=[];try{const r=await fetch('/api/history?limit=30',{headers:teamHeaders()});const x=await r.json();if(r.ok)history=x.history||[]}catch{}const role=teamRole||'local';showModal(`<div class="modal-head"><h2>Team Sync & Governance <span class="v2-version">v${APP_VERSION}</span></h2><button class="btn sm" onclick="closeModal()">×</button></div><div class="modal-body"><div class="governance-grid"><div class="governance-box"><div class="section-title">Team identity</div><div class="ff"><label>User / editor name</label><input id="teamUserName" value="${esc(teamUser())}"></div><div class="ff" style="margin-top:8px"><label>Access token (optional server security)</label><input id="teamToken" type="password" placeholder="Configured on Render" value="${esc(teamToken())}"></div><button class="btn" style="margin-top:9px" onclick="setTeamIdentity()">Apply</button><div class="small" style="margin-top:7px">Role: <span class="role-badge">${esc(role)}</span></div></div><div class="governance-box"><div class="section-title">Shared team mode</div><label class="dashboard-flag show"><input type="checkbox" ${state.settings?.teamSync?'checked':''} onchange="setTeamSync(this.checked)"><span>Auto-sync team state</span></label><div class="small" style="margin-top:8px">Optimistic revision control prevents silent overwrites. Local mode remains available for offline work.</div><div style="display:flex;gap:6px;margin-top:10px"><button class="btn sm" onclick="loadServerState()">Pull latest</button><button class="btn sm primary" onclick="syncServer()">Push now</button></div></div><div class="governance-box"><div class="section-title">Control Tower model</div><div class="small">Schema v3 · Project → Task → Phase/Sub-Task → Activity/Milestone</div><div class="small" style="margin-top:6px">Progress: reported or weighted calculated</div><div class="small" style="margin-top:6px">Primary live milestone supported</div><div class="small" style="margin-top:6px">Revision: ${serverRevision||0}</div></div></div><div class="section-title" style="margin-top:18px">Audit history</div><div class="history-list">${history.map(h=>`<div class="history-row"><b>r${h.revision}</b><div><div>${esc(h.action||'save')}</div><div class="small">${esc(h.user||'unknown')} · ${new Date(h.at).toLocaleString()}</div></div>${role==='admin'&&Number(h.revision)<Number(serverRevision)&&String(h.action||'').startsWith('restore')===false?`<button class="btn sm" onclick="restoreTeamRevision(${h.revision})">Restore</button>`:''}</div>`).join('')||'<div class="empty">No server history or not connected.</div>'}</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Close</button></div>`)}
async function restoreTeamRevision(rev){if(!confirm(`Restore team data to revision ${rev}? Current state will be preserved as a new revision.`))return;try{const r=await fetch('/api/restore/'+rev,{method:'POST',headers:teamHeaders()});const x=await r.json();if(!r.ok)throw new Error(x.error||'Restore failed');serverRevision=Number(x.revision||serverRevision);await loadServerState();openTeamCenter()}catch(e){alert(e.message)}}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function project(id=state.selectedProjectId){return state.projects.find(p=>p.id===id)||state.projects[0]}
function ms(key){return state.masters.milestones.find(m=>m.key===key)||{key,name:key,color:'#526274',units:[]}}
function statusPill(s){const cls=s==='InProgress'?'InProgress':s;return `<span class="pill st-${cls}">${STATUS_LABEL[s]||s}</span>`}
function dateVal(s){return s?new Date(s+'T12:00:00').getTime():0}
function days(a,b){return Math.round((dateVal(b)-dateVal(a))/86400000)}
function calculatedProgress(p){const a=p.activities||[];if(!a.length)return 0;const score={Completed:100,InProgress:50,AtRisk:40,Delayed:35,OnHold:25,Upcoming:0};let weighted=0,total=0;for(const x of a){const w=Math.max(.1,Number(x.weight||1));weighted+=(score[x.status]??0)*w;total+=w}return total?Math.round(weighted/total):0}
function progress(p){if(p.progressMode==='reported'&&Number.isFinite(Number(p.reportedProgress)))return Math.max(0,Math.min(100,Math.round(Number(p.reportedProgress))));return calculatedProgress(p)}
function projectStatus(p){const a=p.activities||[];if(!a.length)return'Upcoming';if(a.every(x=>x.status==='Completed'))return'Completed';if(a.some(x=>x.status==='Delayed'))return'Delayed';if(a.some(x=>x.status==='AtRisk'))return'AtRisk';if(a.some(x=>x.status==='OnHold'))return'OnHold';if(a.some(x=>x.status==='InProgress'))return'OnTrack';return'Upcoming'}
function overdueSteps(p){const today=dateVal(dateOffset(0));return (p.activities||[]).flatMap(a=>(a.nextSteps||[]).map(s=>({a,s}))).filter(x=>x.s.status!=='Completed'&&dateVal(x.s.due)<today)}
function upcomingActivities(p,n=14){const t=dateVal(dateOffset(0)),end=t+n*86400000;return (p.activities||[]).filter(a=>dateVal(a.plannedEnd)>=t&&dateVal(a.plannedEnd)<=end&&a.status!=='Completed').sort((a,b)=>dateVal(a.plannedEnd)-dateVal(b.plannedEnd))}
function completedRecent(p,n=21){const t=dateVal(dateOffset(0))-n*86400000;return (p.activities||[]).filter(a=>a.status==='Completed'&&dateVal(a.actualEnd||a.plannedEnd)>=t).sort((a,b)=>dateVal(b.actualEnd||b.plannedEnd)-dateVal(a.actualEnd||a.plannedEnd))}
function setPage(p){page=p;render()}
function renderNav(){const items=[['dashboard','Dashboard'],['projects','Project List'],['detail','Detail Plan'],['presentation','Presentation'],['master','Master Data']];document.getElementById('nav').innerHTML=items.map(([k,l])=>`<button class="${page===k?'active':''}" onclick="setPage('${k}')">${l}</button>`).join('')}
function render(){renderNav();const root=document.getElementById('root'); if(page==='dashboard')root.innerHTML=renderDashboard(); if(page==='projects')root.innerHTML=renderProjects(); if(page==='detail'){root.innerHTML=renderDetail();initGanttInteractions()} if(page==='presentation')root.innerHTML=renderPresentation(); if(page==='master')root.innerHTML=renderMaster();}
function startOfWeekMs(msv){const d=new Date(msv);d.setHours(12,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.getTime()}
function isoWeek(d){const x=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));x.setUTCDate(x.getUTCDate()+4-(x.getUTCDay()||7));const y=new Date(Date.UTC(x.getUTCFullYear(),0,1));return Math.ceil((((x-y)/86400000)+1)/7)}
function dashStatus(p){const s=projectStatus(p);return s==='Completed'?'Completed':s==='AtRisk'?'At Risk':s==='OnTrack'?'On Track':s==='OnHold'?'On Hold':s}
function projectLiveDate(p){const acts=(p.activities||[]).filter(a=>a.plannedStart||a.plannedEnd);const primary=acts.filter(a=>a.isPrimaryLive===true);if(primary.length){const a=primary.slice().sort((a,b)=>dateVal(a.plannedStart||a.plannedEnd)-dateVal(b.plannedStart||b.plannedEnd)).slice(-1)[0];return a.plannedStart||a.plannedEnd||''}const masterLive=acts.filter(a=>ms(a.key).isLiveDefault===true);if(masterLive.length){const a=masterLive.slice().sort((a,b)=>dateVal(a.plannedStart||a.plannedEnd)-dateVal(b.plannedStart||b.plannedEnd)).slice(-1)[0];return a.plannedStart||a.plannedEnd||''}const live=acts.filter(a=>{const t=((a.key||'')+' '+(a.label||'')+' '+(ms(a.key).name||'')).toLowerCase();return t.includes('live')||t.includes('implementation')||t.includes('relaunch')||t.trim().startsWith('go')});const pick=(live.length?live:acts).slice().sort((a,b)=>dateVal(a.plannedStart||a.plannedEnd)-dateVal(b.plannedStart||b.plannedEnd)).slice(-1)[0];return pick?.plannedStart||pick?.plannedEnd||p.plannedEnd||''}
function projectLiveWeek(p){const d=projectLiveDate(p);if(!d)return'-';const dt=new Date(dateVal(d));return 'W'+String(isoWeek(dt)).padStart(2,'0')}
function projectPic(p){const pics=[...new Set((p.activities||[]).flatMap(a=>(a.responsibilities||[]).map(r=>r.pic).filter(Boolean)))];return pics.slice(0,2).join(' / ')||p.owner||'—'}
function sectionName(id){return state.dashboard?.sections?.find(s=>s.id===id)?.name||'Unassigned'}
function dashboardSections(){state.dashboard=state.dashboard||{sections:[]};state.dashboard.sections=state.dashboard.sections||[];return state.dashboard.sections}
function uniqueValues(arr){return [...new Set(arr.filter(v=>v!==undefined&&v!==null&&String(v).trim()!==''))].sort((a,b)=>String(a).localeCompare(String(b)))}
const DASHBOARD_SECTION_FIELDS=[
  {key:'custom',label:'Custom Section'},
  {key:'eventType',label:'Event Type'},
  {key:'format',label:'Format'},
  {key:'division',label:'Division'},
  {key:'department',label:'Department'},
  {key:'owner',label:'Owner'},
  {key:'status',label:'Status'},
  {key:'criticality',label:'Criticality'}
];
const DASHBOARD_SUBSECTION_FIELDS=[
  {key:'none',label:'None'},
  {key:'eventType',label:'Event Type'},
  {key:'format',label:'Format'},
  {key:'division',label:'Division'},
  {key:'department',label:'Department'},
  {key:'owner',label:'Owner'},
  {key:'status',label:'Status'},
  {key:'criticality',label:'Criticality'}
];
function dashboardSectionFieldLabel(){return DASHBOARD_SECTION_FIELDS.find(x=>x.key===dashboardSectionField)?.label||'Custom Section'}
function dashboardSubSectionFieldLabel(){return DASHBOARD_SUBSECTION_FIELDS.find(x=>x.key===dashboardSubSectionField)?.label||'Sub-Section'}
function dashboardFieldValue(p,field){if(field==='custom')return p.dashboardSectionId||'';if(field==='status')return dashStatus(p)||'Unassigned';return String(p[field]||'').trim()||'Unassigned'}
function dashboardGroupKey(p){return dashboardFieldValue(p,dashboardSectionField)}
function dashboardSubGroupKey(p){return dashboardSubSectionField==='none'?'':dashboardFieldValue(p,dashboardSubSectionField)}
function dashboardGroupLabel(key){if(dashboardSectionField==='custom')return sectionName(key);return key||'Unassigned'}
function dashboardSubGroupLabel(key){return key||'Unassigned'}
function dashboardGroupOptions(all){if(dashboardSectionField==='custom'){const configured=dashboardSections();const opts=configured.map(s=>({value:s.id,label:s.name}));if(all.some(p=>!p.dashboardSectionId||!configured.some(s=>s.id===p.dashboardSectionId)))opts.push({value:'',label:'Unassigned'});return opts}const vals=uniqueValues(all.map(p=>dashboardGroupKey(p)));if(dashboardSectionField==='status'){const order=['Upcoming','On Track','At Risk','Delayed','On Hold','Completed','Unassigned'];vals.sort((a,b)=>order.indexOf(a)-order.indexOf(b))}return vals.map(v=>({value:v,label:v}))}
function dashboardSubGroupOptions(all){if(dashboardSubSectionField==='none')return[];const vals=uniqueValues(all.map(p=>dashboardSubGroupKey(p)));if(dashboardSubSectionField==='status'){const order=['Upcoming','On Track','At Risk','Delayed','On Hold','Completed','Unassigned'];vals.sort((a,b)=>order.indexOf(a)-order.indexOf(b))}return vals.map(v=>({value:v,label:v}))}
function dashboardFilteredProjects(){let ps=state.projects.filter(p=>p.showOnDashboard!==false);const f=dashboardFilter;if(f.search){const q=f.search.toLowerCase();ps=ps.filter(p=>[p.code,p.name,p.summary,p.eventType,p.owner,p.format,p.division,p.department].some(v=>String(v||'').toLowerCase().includes(q)))}if(f.eventType!=='All')ps=ps.filter(p=>p.eventType===f.eventType);if(f.status!=='All')ps=ps.filter(p=>dashStatus(p)===f.status);if(f.owner!=='All')ps=ps.filter(p=>p.owner===f.owner);if(f.section!=='All')ps=ps.filter(p=>dashboardGroupKey(p)===f.section);if(f.subSection!=='All'&&dashboardSubSectionField!=='none')ps=ps.filter(p=>dashboardSubGroupKey(p)===f.subSection);return ps}
function dashboardSortMeta(){const s=dashboardSort;if(s==='eventTypeDesc')return['eventType','desc'];if(s==='eventTypeAsc'||s==='eventType')return['eventType','asc'];if(s==='formatDesc')return['format','desc'];if(s==='formatAsc'||s==='format')return['format','asc'];if(s==='projectDesc')return['project','desc'];if(s==='projectAsc')return['project','asc'];if(s==='liveDesc')return['live','desc'];if(s==='liveAsc')return['live','asc'];if(s==='statusDesc')return['status','desc'];if(s==='statusAsc'||s==='status')return['status','asc'];if(s==='planStartDesc')return['planStart','desc'];if(s==='planStartAsc'||s==='planStart')return['planStart','asc'];return['live','asc']}
function compareDashboard(a,b){const [key,dir]=dashboardSortMeta();let c=0;if(key==='live')c=dateVal(projectLiveDate(a))-dateVal(projectLiveDate(b));else if(key==='project')c=String(a.name||'').localeCompare(String(b.name||''));else if(key==='eventType')c=String(a.eventType||'').localeCompare(String(b.eventType||''));else if(key==='format')c=String(a.format||'').localeCompare(String(b.format||''));else if(key==='status')c=dashStatus(a).localeCompare(dashStatus(b));else if(key==='planStart')c=dateVal(a.plannedStart)-dateVal(b.plannedStart);if(c===0)c=String(a.name||'').localeCompare(String(b.name||''));return dir==='desc'?-c:c}
function setDashboardFilter(k,v){dashboardFilter[k]=v;render()}
function setDashboardSectionField(v){dashboardSectionField=v;state.dashboard=state.dashboard||{sections:[]};state.dashboard.groupBy=v;dashboardFilter.section='All';if(dashboardSubSectionField===v&&v!=='custom')setDashboardSubSectionField('none',false);save();render()}
function setDashboardSubSectionField(v,rerender=true){dashboardSubSectionField=v;state.dashboard=state.dashboard||{sections:[]};state.dashboard.subGroupBy=v;dashboardFilter.subSection='All';save();if(rerender)render()}
function setDashboardSortHeader(key){const [current,dir]=dashboardSortMeta();const nextDir=current===key&&dir==='asc'?'desc':'asc';dashboardSort=key+nextDir.charAt(0).toUpperCase()+nextDir.slice(1);render()}
function setDashboardTimelineGroup(v){dashboardTimelineGroup=v;state.dashboard=state.dashboard||{sections:[]};state.dashboard.timelineGroup=v;save();render()}
function setDashboardTimeMode(v){dashboardTimeMode=v;state.dashboard=state.dashboard||{sections:[]};state.dashboard.timeMode=v;save();render()}
function setDashboardZoom(v){dashboardZoom=Math.max(25,Math.min(200,Number(v)||100));state.dashboard=state.dashboard||{sections:[]};state.dashboard.zoom=dashboardZoom;save();render()}
function dashboardSavedViews(){state.dashboard=state.dashboard||{};state.dashboard.savedViews=Array.isArray(state.dashboard.savedViews)?state.dashboard.savedViews:[];return state.dashboard.savedViews}
function saveDashboardView(){const name=prompt('Saved view name');if(!name||!name.trim())return;const v={id:'view-'+uid(),name:name.trim(),filter:clone(dashboardFilter),sort:dashboardSort,groupMode:dashboardGroupMode,sectionField:dashboardSectionField,subSectionField:dashboardSubSectionField,timelineGroup:dashboardTimelineGroup,timeMode:dashboardTimeMode,zoom:dashboardZoom};state.dashboard.savedViews.push(v);activeSavedView=v.id;save();render()}
function applyDashboardView(id){if(!id){activeSavedView='';return}const v=dashboardSavedViews().find(x=>x.id===id);if(!v)return;activeSavedView=id;dashboardFilter={...dashboardFilter,...clone(v.filter||{})};dashboardSort=v.sort||'liveAsc';dashboardGroupMode=v.groupMode||'section';dashboardSectionField=v.sectionField||'custom';dashboardSubSectionField=v.subSectionField||'none';dashboardTimelineGroup=v.timelineGroup||'subtask';dashboardTimeMode=v.timeMode||'Week';dashboardZoom=Number(v.zoom||100);state.dashboard.groupBy=dashboardSectionField;state.dashboard.subGroupBy=dashboardSubSectionField;state.dashboard.timelineGroup=dashboardTimelineGroup;state.dashboard.timeMode=dashboardTimeMode;state.dashboard.zoom=dashboardZoom;save();render()}
function deleteDashboardView(){if(!activeSavedView)return;const v=dashboardSavedViews().find(x=>x.id===activeSavedView);if(!v||!confirm(`Delete saved view "${v.name}"?`))return;state.dashboard.savedViews=state.dashboard.savedViews.filter(x=>x.id!==activeSavedView);activeSavedView='';save();render()}
function fitDashboardTimeline(){const ps=dashboardFilteredProjects();if(!ps.length)return;const day=86400000;const vals=ps.flatMap(p=>[p.plannedStart,p.plannedEnd,...(p.activities||[]).flatMap(a=>[a.plannedStart,a.plannedEnd])]).filter(Boolean).map(dateVal);if(!vals.length)return;const span=Math.max(14,(Math.max(...vals)-Math.min(...vals))/day+14);const base=dashboardTimeMode==='Day'?30:dashboardTimeMode==='Month'?4:52/7;const available=Math.max(500,window.innerWidth-760);setDashboardZoom(Math.max(25,Math.min(200,Math.round((available/(span*base))*100/25)*25)))}
function scrollDashboardToday(){requestAnimationFrame(()=>{const wrap=document.querySelector('.portfolio-gantt-wrap'),badge=document.querySelector('.portfolio-now-badge');if(!wrap||!badge)return;const x=badge.getBoundingClientRect().left-wrap.getBoundingClientRect().left+wrap.scrollLeft;wrap.scrollTo({left:Math.max(0,x-wrap.clientWidth*.62),behavior:'smooth'})})}
function collapsedProjectIds(){state.dashboard=state.dashboard||{};state.dashboard.collapsedProjects=Array.isArray(state.dashboard.collapsedProjects)?state.dashboard.collapsedProjects:[];return state.dashboard.collapsedProjects}
function collapsedTaskKeys(){state.dashboard=state.dashboard||{};state.dashboard.collapsedTasks=Array.isArray(state.dashboard.collapsedTasks)?state.dashboard.collapsedTasks:[];return state.dashboard.collapsedTasks}
function taskCollapseKey(projectId,task){return `${projectId}|||${task||'Unassigned Task'}`}
function isProjectCollapsed(id){return collapsedProjectIds().includes(id)}
function isTaskCollapsed(projectId,task){return collapsedTaskKeys().includes(taskCollapseKey(projectId,task))}
function toggleProjectPhasing(id){const a=collapsedProjectIds();state.dashboard.collapsedProjects=a.includes(id)?a.filter(x=>x!==id):[...a,id];save();render()}
function toggleTaskPhasing(projectId,task){const key=taskCollapseKey(projectId,task),a=collapsedTaskKeys();state.dashboard.collapsedTasks=a.includes(key)?a.filter(x=>x!==key):[...a,key];save();render()}
function setAllProjectPhasing(collapsed){state.dashboard.collapsedProjects=collapsed?state.projects.map(p=>p.id):[];if(!collapsed)state.dashboard.collapsedTasks=[];save();render()}
function sortIndicator(key){const [current,dir]=dashboardSortMeta();return current===key?`<span class="sort-indicator">${dir==='asc'?'▲':'▼'}</span>`:'<span class="sort-indicator">↕</span>'}
function clearDashboardFilters(){dashboardFilter={search:'',eventType:'All',status:'All',section:'All',subSection:'All',owner:'All'};dashboardSort='liveAsc';render()}
// removed legacy renderDashboard
function renderDashboard(){const all=state.projects.filter(p=>p.showOnDashboard!==false),ps=dashboardFilteredProjects().sort(compareDashboard);const now=new Date(),q=Math.floor(now.getMonth()/3)+1;const events=uniqueValues(all.map(p=>p.eventType)),owners=uniqueValues(all.map(p=>p.owner)),groupOptions=dashboardGroupOptions(all),subGroupOptions=dashboardSubGroupOptions(all);const subFieldOptions=DASHBOARD_SUBSECTION_FIELDS.filter(x=>x.key==='none'||x.key!==dashboardSectionField);const views=dashboardSavedViews();const atRisk=all.filter(p=>['AtRisk','Delayed','OnHold'].includes(projectStatus(p))).length,completed=all.filter(p=>projectStatus(p)==='Completed').length,overdue=all.reduce((n,p)=>n+overdueSteps(p).length,0),capacity=Math.round(all.reduce((n,p)=>n+Number(p.capacityHours||0),0)*10)/10;const live28=all.filter(p=>{const d=dateVal(projectLiveDate(p)),t=dateVal(dateOffset(0));return d>=t&&d<=t+28*86400000}).length;return `<div class="page"><div class="portfolio-head"><div class="portfolio-title"><h1>Range Operation: Project update <span class="v2-version">v${APP_VERSION}</span></h1><div class="portfolio-period">Q${q}-${now.getFullYear()}</div></div><div style="display:flex;align-items:center;gap:12px"><div class="portfolio-legend"><span><i class="legend-phase"></i>Active Phase</span><span><i class="legend-ms"></i>Milestone</span></div>${dashboardSectionField==='custom'?`<button class="btn" onclick="openSectionManager()">Manage Custom Sections</button>`:''}<button class="btn primary" onclick="openProjectModal()">+ New Project</button></div></div><div class="metric-strip"><div class="mini"><span>Projects shown</span><b>${all.length}</b></div><div class="mini"><span>Completed</span><b>${completed}</b></div><div class="mini"><span>At risk / delayed</span><b class="${atRisk?'danger-text':''}">${atRisk}</b></div><div class="mini"><span>Live next 4 weeks</span><b>${live28}</b></div><div class="mini"><span>Overdue actions</span><b class="${overdue?'danger-text':''}">${overdue}</b></div><div class="mini"><span>Planned capacity</span><b>${capacity}h</b></div></div><div class="dashboard-controls"><div class="dashboard-control search"><label>Search</label><input value="${esc(dashboardFilter.search)}" placeholder="Project / code / update" oninput="dashboardFilter.search=this.value;render()"></div><div class="dashboard-control"><label>Event Type</label><select onchange="setDashboardFilter('eventType',this.value)"><option>All</option>${events.map(v=>`<option ${dashboardFilter.eventType===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="dashboard-control"><label>Status</label><select onchange="setDashboardFilter('status',this.value)">${['All','Upcoming','On Track','Completed','At Risk','Delayed','On Hold'].map(v=>`<option ${dashboardFilter.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="dashboard-control"><label>Owner</label><select onchange="setDashboardFilter('owner',this.value)"><option>All</option>${owners.map(v=>`<option ${dashboardFilter.owner===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="dashboard-control"><label>Section by</label><select onchange="setDashboardSectionField(this.value)">${DASHBOARD_SECTION_FIELDS.map(x=>`<option value="${x.key}" ${dashboardSectionField===x.key?'selected':''}>${x.label}</option>`).join('')}</select></div><div class="dashboard-control"><label>Sub-Section by</label><select onchange="setDashboardSubSectionField(this.value)">${subFieldOptions.map(x=>`<option value="${x.key}" ${dashboardSubSectionField===x.key?'selected':''}>${x.label}</option>`).join('')}</select></div><div class="dashboard-control"><label>${esc(dashboardSectionFieldLabel())}</label><select onchange="setDashboardFilter('section',this.value)"><option value="All">All</option>${groupOptions.map(o=>`<option value="${esc(o.value)}" ${dashboardFilter.section===o.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></div>${dashboardSubSectionField!=='none'?`<div class="dashboard-control"><label>${esc(dashboardSubSectionFieldLabel())}</label><select onchange="setDashboardFilter('subSection',this.value)"><option value="All">All</option>${subGroupOptions.map(o=>`<option value="${esc(o.value)}" ${dashboardFilter.subSection===o.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></div>`:''}<div class="dashboard-control"><label>Timeline rows</label><select onchange="setDashboardTimelineGroup(this.value)"><option value="subtask" ${dashboardTimelineGroup!=='project'?'selected':''}>Sub-Task Phasing</option><option value="project" ${dashboardTimelineGroup==='project'?'selected':''}>Project Summary</option></select></div><div class="dashboard-control"><label>Time scale</label><select onchange="setDashboardTimeMode(this.value)"><option ${dashboardTimeMode==='Month'?'selected':''}>Month</option><option ${dashboardTimeMode==='Week'?'selected':''}>Week</option><option ${dashboardTimeMode==='Day'?'selected':''}>Day</option></select></div><div class="dashboard-control"><label>Zoom</label><div class="dashboard-command"><button class="btn sm" onclick="setDashboardZoom(dashboardZoom-25)">−</button><span class="small" style="min-width:42px;text-align:center;font-weight:800">${dashboardZoom}%</span><button class="btn sm" onclick="setDashboardZoom(dashboardZoom+25)">+</button><button class="btn sm" onclick="fitDashboardTimeline()">Fit</button><button class="btn sm" onclick="scrollDashboardToday()">Today</button></div></div><div class="dashboard-control"><label>Report View</label><select onchange="dashboardGroupMode=this.value;render()"><option value="section" ${dashboardGroupMode==='section'?'selected':''}>Grouped Sections</option><option value="flat" ${dashboardGroupMode==='flat'?'selected':''}>All Projects</option></select></div><div class="dashboard-control"><label>Saved View</label><div class="dashboard-presets"><select onchange="applyDashboardView(this.value)"><option value="">Custom</option>${views.map(v=>`<option value="${v.id}" ${activeSavedView===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select><button class="btn sm" onclick="saveDashboardView()">Save</button>${activeSavedView?'<button class="btn sm danger" onclick="deleteDashboardView()">×</button>':''}</div></div><div class="dashboard-control-actions"><button class="btn" onclick="clearDashboardFilters()">Clear</button><button class="btn sm" onclick="setAllProjectPhasing(false)">Expand All</button><button class="btn sm" onclick="setAllProjectPhasing(true)">Collapse All</button><span class="small">${ps.length}/${all.length} projects</span></div></div>${renderPortfolioGantt(ps)}</div>`}

function milestoneTextHalf(a){try{milestoneTextHalf.canvas=milestoneTextHalf.canvas||document.createElement('canvas');const ctx=milestoneTextHalf.canvas.getContext('2d');ctx.font='700 10px Inter, system-ui, sans-serif';const label=String(a.label||a.key||'')+' '+new Date(dateVal(a.plannedStart)).toLocaleDateString('en',{day:'2-digit',month:'short'});return Math.max(30,Math.min(90,ctx.measureText(label).width/2+8))}catch{return 43}}
function milestoneLayout(acts,min,width,pxPerDay){const day=86400000;const points=acts.map((a,i)=>{const x=(dateVal(a.plannedStart)-min)/day*pxPerDay;const half=milestoneTextHalf(a);return {a,x,half,i}}).filter(o=>o.x>=0&&o.x<=width).sort((a,b)=>a.x-b.x||a.i-b.i);const lastRight=[];for(const p of points){let level=0;while(level<lastRight.length&&p.x-p.half<=lastRight[level]+8)level++;p.level=level;lastRight[level]=p.x+p.half;}return {points,maxLevel:points.reduce((m,p)=>Math.max(m,p.level),0)}}
function renderPortfolioGantt(ps){if(!ps.length)return`<div class="card portfolio-empty">No projects match the current dashboard filters.</div>`;const day=86400000,leftW=721;const starts=ps.flatMap(p=>[p.plannedStart,...(p.activities||[]).map(a=>a.plannedStart)]).filter(Boolean).map(dateVal);const ends=ps.flatMap(p=>[p.plannedEnd,...(p.activities||[]).map(a=>a.plannedEnd)]).filter(Boolean).map(dateVal);const today=dateVal(dateOffset(0));
const localNoon=msv=>{const d=new Date(msv);d.setHours(12,0,0,0);return d.getTime()};
const addDaysLocal=(msv,n)=>{const d=new Date(msv);d.setHours(12,0,0,0);d.setDate(d.getDate()+n);return d.getTime()};
const monthStartLocal=msv=>{const d=new Date(msv);d.setHours(12,0,0,0);d.setDate(1);return d.getTime()};
const addMonthsLocal=(msv,n)=>{const d=new Date(msv);d.setHours(12,0,0,0);d.setDate(1);d.setMonth(d.getMonth()+n);return d.getTime()};
let min=localNoon(Math.min(today,...starts)),max=localNoon(Math.max(today,...ends));let pxPerDay=52/7,gridStep=52;
const zoomFactor=dashboardZoom/100;if(dashboardTimeMode==='Day'){min=addDaysLocal(min,-3);max=addDaysLocal(max,5);pxPerDay=30*zoomFactor;gridStep=pxPerDay}else if(dashboardTimeMode==='Month'){min=addMonthsLocal(monthStartLocal(min),-1);max=addMonthsLocal(monthStartLocal(max),2);pxPerDay=4*zoomFactor;gridStep=30.44*pxPerDay}else{min=startOfWeekMs(addDaysLocal(min,-7));max=addDaysLocal(startOfWeekMs(addDaysLocal(max,14)),7);pxPerDay=(52/7)*zoomFactor;gridStep=52*zoomFactor}
const width=Math.max(900,Math.ceil((max-min)/day*pxPerDay));const xOf=msv=>(msv-min)/day*pxPerDay;const todayX=xOf(today);
const monthGroups=[];let mc=monthStartLocal(min);while(mc<max){const nx=addMonthsLocal(mc,1),s=Math.max(min,mc),e=Math.min(max,nx);if(e>s){monthGroups.push({start:s,end:e,left:xOf(s),width:xOf(e)-xOf(s),label:new Date(mc).toLocaleDateString('en',{month:'short'}),year:new Date(mc).getFullYear()})}mc=nx}
const months=monthGroups.map(m=>`<div class="portfolio-month" style="left:${m.left}px;width:${m.width}px">${esc(m.label)} ${m.year}</div>`).join('');
let axisExtra='';
if(dashboardTimeMode==='Day'){let weeks='';let ws=startOfWeekMs(min);while(ws<max){const we=addDaysLocal(ws,7),s=Math.max(min,ws),e=Math.min(max,we);if(e>s)weeks+=`<div class="portfolio-week" style="left:${xOf(s)}px;width:${xOf(e)-xOf(s)}px">W${String(isoWeek(new Date(ws))).padStart(2,'0')}</div>`;ws=we}let daysHtml='';let dc=localNoon(min);while(dc<max){const ne=addDaysLocal(dc,1),s=Math.max(min,dc),e=Math.min(max,ne),dt=new Date(dc);if(e>s)daysHtml+=`<div class="portfolio-day ${[0,6].includes(dt.getDay())?'weekend':''}" style="left:${xOf(s)}px;width:${xOf(e)-xOf(s)}px" title="${dt.toLocaleDateString('en',{weekday:'short',day:'2-digit',month:'short',year:'numeric'})}">${String(dt.getDate()).padStart(2,'0')}</div>`;dc=ne}axisExtra=`<div class="portfolio-weeks">${weeks}</div><div class="portfolio-days">${daysHtml}</div>`}
else if(dashboardTimeMode==='Week'){let weeks='';let ws=startOfWeekMs(min);while(ws<max){const we=addDaysLocal(ws,7),s=Math.max(min,ws),e=Math.min(max,we);if(e>s)weeks+=`<div class="portfolio-week" style="left:${xOf(s)}px;width:${xOf(e)-xOf(s)}px" title="Week starting ${new Date(ws).toLocaleDateString('en',{day:'2-digit',month:'short',year:'numeric'})}">W${String(isoWeek(new Date(ws))).padStart(2,'0')}</div>`;ws=we}axisExtra=`<div class="portfolio-weeks">${weeks}</div>`}
else{const yearGroups=[];for(const m of monthGroups){const last=yearGroups[yearGroups.length-1];if(last&&last.year===m.year){last.end=m.end;last.width=xOf(last.end)-last.left}else{yearGroups.push({year:m.year,start:m.start,end:m.end,left:xOf(m.start),width:xOf(m.end)-xOf(m.start)})}}axisExtra=`<div class="portfolio-years">${yearGroups.map(y=>`<div class="portfolio-year" style="left:${y.left}px;width:${y.width}px">${y.year}</div>`).join('')}</div>`}
const childTimelineRow=(subTask,task,childActs)=>{const dated=childActs.filter(a=>a.plannedStart&&a.plannedEnd).slice().sort((a,b)=>dateVal(a.plannedStart)-dateVal(b.plannedStart));if(!dated.length)return'';const cStart=Math.max(min,Math.min(...dated.map(a=>dateVal(a.plannedStart)))),cEnd=Math.min(max,Math.max(...dated.map(a=>dateVal(a.plannedEnd)))+day);const startX=Math.max(0,xOf(cStart)),endX=Math.min(width,xOf(cEnd)),barW=Math.max(3,endX-startX);const layout=milestoneLayout(dated,min,width,pxPerDay);const rowH=Math.max(58,58+layout.maxLevel*25);const phaseTop=rowH-19,markerTop=phaseTop-18;const labels=layout.points.map(o=>{const a=o.a,m=ms(a.key),labelTop=4+o.level*25,stemTop=labelTop+23,stemH=Math.max(2,markerTop-stemTop),startLabel=new Date(dateVal(a.plannedStart)).toLocaleDateString('en',{day:'2-digit',month:'short'});const title=`${m.key} · ${m.name}\n${a.task} → ${a.subTask}\nStart ${a.plannedStart}\nEnd ${a.plannedEnd}\n${STATUS_LABEL[a.status]||a.status}`;return `<span class="portfolio-ms-label" style="left:${o.x}px;--ms-label-top:${labelTop}px" title="${esc(title)}"><b>${esc(a.key)}</b><small>${esc(startLabel)}</small></span><i class="portfolio-ms-stem" style="left:${o.x}px;top:${stemTop}px;height:${stemH}px"></i><i class="portfolio-milestone ${a.isCriticalPath?'critical':''}" style="left:${o.x}px;--ms-marker-top:${markerTop}px" title="${esc(title)}"></i>`}).join('');return `<div class="portfolio-child-row subtask-row" style="--child-row-height:${rowH}px"><div class="portfolio-child-spacer"></div><div class="portfolio-child-spacer"></div><div class="portfolio-child-title subtask"><span class="hierarchy-branch">↳</span><div><span class="phasing-name">${esc(subTask)}</span><span class="phasing-parent">Sub-Task / Phase · ${esc(task)}</span></div><span class="portfolio-child-badge">${dated.length}</span></div><div class="portfolio-child-meta-blank"></div><div class="portfolio-child-meta-blank"></div><div class="portfolio-child-track" style="width:${width}px;background-size:${gridStep}px 100%;--child-row-height:${rowH}px"><div class="portfolio-phase" style="left:${startX}px;width:${barW}px" title="${esc(task)} → ${esc(subTask)}"></div>${labels}</div></div>`};
const taskTimelineRow=(p,task,taskActs)=>{const dated=taskActs.filter(a=>a.plannedStart&&a.plannedEnd).slice().sort((a,b)=>dateVal(a.plannedStart)-dateVal(b.plannedStart));if(!dated.length)return'';const tStart=Math.max(min,Math.min(...dated.map(a=>dateVal(a.plannedStart)))),tEnd=Math.min(max,Math.max(...dated.map(a=>dateVal(a.plannedEnd)))+day),startX=Math.max(0,xOf(tStart)),endX=Math.min(width,xOf(tEnd)),barW=Math.max(3,endX-startX);const collapsed=isTaskCollapsed(p.id,task);const subs=new Map();dated.forEach(a=>{const sub=a.subTask||'Unassigned Sub Task';if(!subs.has(sub))subs.set(sub,[]);subs.get(sub).push(a)});const subRows=collapsed?'':[...subs.entries()].sort((a,b)=>Math.min(...a[1].map(x=>dateVal(x.plannedStart)))-Math.min(...b[1].map(x=>dateVal(x.plannedStart)))).map(([sub,items])=>childTimelineRow(sub,task,items)).join('');return `<div class="portfolio-child-row task-row" style="--child-row-height:42px"><div class="portfolio-child-spacer"></div><div class="portfolio-child-spacer"></div><div class="portfolio-child-title task"><button class="collapse-toggle task-toggle" onclick="event.stopPropagation();toggleTaskPhasing('${p.id}',${JSON.stringify(task)})" title="${collapsed?'Expand':'Collapse'} Task">${collapsed?'＋':'−'}</button><div><span class="phasing-name">${esc(task)}</span><span class="phasing-parent">Task / Workstream · ${subs.size} sub-task(s)</span></div><span class="portfolio-child-badge">${dated.length}</span></div><div class="portfolio-child-meta-blank"></div><div class="portfolio-child-meta-blank"></div><div class="portfolio-child-track task-track" style="width:${width}px;background-size:${gridStep}px 100%;--child-row-height:42px"><div class="portfolio-phase" style="left:${startX}px;width:${barW}px" title="Task: ${esc(task)}"></div></div></div>${subRows}`};
const rowHtml=p=>{const acts=(p.activities||[]).filter(a=>a.plannedStart&&a.plannedEnd).slice().sort((a,b)=>dateVal(a.plannedStart)-dateVal(b.plannedStart));const validStart=p.plannedStart||acts[0]?.plannedStart||dateOffset(0),validEnd=p.plannedEnd||acts[acts.length-1]?.plannedEnd||validStart;const pStart=Math.max(min,dateVal(validStart)),pEnd=Math.min(max,dateVal(validEnd)+day);const startX=Math.max(0,xOf(pStart)),endX=Math.min(width,xOf(pEnd)),barW=Math.max(3,endX-startX);const showProjectMilestones=dashboardTimelineGroup==='project';const layout=showProjectMilestones?milestoneLayout(acts,min,width,pxPerDay):{points:[],maxLevel:0};const rowH=showProjectMilestones?Math.max(96,96+layout.maxLevel*28):62;const phaseTop=rowH-26,markerTop=phaseTop-18;const labels=layout.points.map(o=>{const a=o.a,m=ms(a.key),labelTop=6+o.level*28,stemTop=labelTop+25,stemH=Math.max(2,markerTop-stemTop);const startLabel=new Date(dateVal(a.plannedStart)).toLocaleDateString('en',{day:'2-digit',month:'short'});const title=`${m.key} · ${m.name}\nStart ${a.plannedStart}\nEnd ${a.plannedEnd}\n${STATUS_LABEL[a.status]||a.status}`;return `<span class="portfolio-ms-label" style="left:${o.x}px;--ms-label-top:${labelTop}px" title="${esc(title)}"><b>${esc(a.key)}</b><small>${esc(startLabel)}</small></span><i class="portfolio-ms-stem" style="left:${o.x}px;top:${stemTop}px;height:${stemH}px"></i><i class="portfolio-milestone ${a.isCriticalPath?'critical':''}" style="left:${o.x}px;--ms-marker-top:${markerTop}px" title="${esc(title)}"></i>`}).join('');const stat=dashStatus(p),cls=stat==='Delayed'?'delay':stat==='At Risk'?'risk':'';const summary=p.risk?`Issue: ${p.risk}`:(p.summary||p.eventType||'');let children='';if(dashboardTimelineGroup!=='project'&&!isProjectCollapsed(p.id)){const tasks=new Map();acts.forEach(a=>{const task=a.task||'Unassigned Task';if(!tasks.has(task))tasks.set(task,[]);tasks.get(task).push(a)});children=[...tasks.entries()].sort((a,b)=>Math.min(...a[1].map(x=>dateVal(x.plannedStart)))-Math.min(...b[1].map(x=>dateVal(x.plannedStart)))).map(([task,items])=>taskTimelineRow(p,task,items)).join('')}return `<div class="portfolio-row" style="min-height:${rowH}px;--row-height:${rowH}px"><div class="portfolio-event">${esc(p.eventType||'-')}</div><div class="portfolio-format">${esc(p.format||'-')}</div><div class="portfolio-process"><div>${dashboardTimelineGroup!=='project'?`<button class="collapse-toggle project-toggle" onclick="event.stopPropagation();toggleProjectPhasing('${p.id}')" title="${isProjectCollapsed(p.id)?'Expand':'Collapse'} Project">${isProjectCollapsed(p.id)?'＋':'−'}</button>`:''}<span class="project-link" onclick="openDetail('${p.id}')">${esc(p.name)}</span></div><div class="portfolio-process-summary">${esc(summary)}</div></div><div class="portfolio-live" title="${esc(projectLiveDate(p))}">${esc(projectLiveWeek(p))}</div><div class="portfolio-status ${cls}">${esc(stat)}</div><div class="portfolio-track" style="width:${width}px;background-size:${gridStep}px 100%;--row-height:${rowH}px"><div class="portfolio-phase" style="left:${startX}px;width:${barW}px" title="${esc(p.plannedStart)} → ${esc(p.plannedEnd)}"></div>${labels}</div></div>${children}`};
const primaryGroups=()=>{const groups=[];if(dashboardSectionField==='custom'){const configured=dashboardSections();configured.forEach(s=>{const items=ps.filter(p=>dashboardGroupKey(p)===s.id).sort(compareDashboard);if(items.length)groups.push({id:s.id,name:s.name,items})});const unassigned=ps.filter(p=>dashboardGroupKey(p)==='').sort(compareDashboard);if(unassigned.length)groups.push({id:'',name:'Unassigned',items:unassigned})}else{const keys=uniqueValues(ps.map(p=>dashboardGroupKey(p)));if(dashboardSectionField==='status'){const order=['Upcoming','On Track','At Risk','Delayed','On Hold','Completed','Unassigned'];keys.sort((a,b)=>order.indexOf(a)-order.indexOf(b))}keys.forEach(key=>{const items=ps.filter(p=>dashboardGroupKey(p)===key).sort(compareDashboard);if(items.length)groups.push({id:key,name:dashboardGroupLabel(key),items})})}return groups};
let body='';if(dashboardGroupMode==='section'){body=primaryGroups().map(g=>{let inside='';if(dashboardSubSectionField==='none'){inside=g.items.map(rowHtml).join('')}else{let keys=uniqueValues(g.items.map(p=>dashboardSubGroupKey(p)));if(dashboardSubSectionField==='status'){const order=['Upcoming','On Track','At Risk','Delayed','On Hold','Completed','Unassigned'];keys.sort((a,b)=>order.indexOf(a)-order.indexOf(b))}inside=keys.map(key=>{const items=g.items.filter(p=>dashboardSubGroupKey(p)===key).sort(compareDashboard);return `<div class="portfolio-subsection-row" style="grid-template-columns:${leftW}px ${width}px"><div class="portfolio-subsection-title">↳ ${esc(dashboardSubGroupLabel(key))} <span class="portfolio-section-count">${items.length}</span></div><div class="portfolio-subsection-time" style="width:${width}px;background-size:${gridStep}px 100%"></div></div>${items.map(rowHtml).join('')}`}).join('')}return `<div class="portfolio-section-row" style="grid-template-columns:${leftW}px ${width}px"><div class="portfolio-section-title">${esc(g.name)} <span class="portfolio-section-count">${g.items.length}</span></div><div class="portfolio-section-time" style="width:${width}px;background-size:${gridStep}px 100%"></div></div>${inside}`}).join('')}else body=ps.slice().sort(compareDashboard).map(rowHtml).join('');return `<div class="portfolio-gantt-wrap"><div class="portfolio-gantt"><div class="portfolio-axis"><div class="portfolio-left-head"><button onclick="setDashboardSortHeader('eventType')">Event Type ${sortIndicator('eventType')}</button><button onclick="setDashboardSortHeader('format')">Format ${sortIndicator('format')}</button><button onclick="setDashboardSortHeader('project')">Project ${sortIndicator('project')}</button><button onclick="setDashboardSortHeader('live')">Live week ${sortIndicator('live')}</button><button onclick="setDashboardSortHeader('status')">Status ${sortIndicator('status')}</button></div><div class="portfolio-time-head" style="width:${width}px"><div class="portfolio-now-badge" style="left:${todayX}px">We're here</div><div class="portfolio-months">${months}</div>${axisExtra}</div></div>${body}<i class="portfolio-today-line" style="left:${leftW+todayX}px"></i></div></div>`}
function openSectionManager(){const sections=dashboardSections();showModal(`<div class="modal-head"><h2>Dashboard Custom Sections</h2><button class="btn sm" onclick="closeModal()">×</button></div><div class="modal-body"><div style="display:flex;gap:8px;margin-bottom:12px"><input id="newSectionName" placeholder="New section name" style="flex:1;border:1px solid var(--line);border-radius:8px;padding:9px"><button class="btn primary" onclick="addDashboardSection()">+ Add Section</button></div><div class="section-manager-list">${sections.map((s,i)=>`<div class="section-manager-row"><div class="section-order">${i+1}</div><div><b>${esc(s.name)}</b><div class="small">${state.projects.filter(p=>p.dashboardSectionId===s.id).length} project(s)</div></div><div><button class="btn sm" onclick="moveDashboardSection(${i},-1)">↑</button> <button class="btn sm" onclick="moveDashboardSection(${i},1)">↓</button> <button class="btn sm" onclick="renameDashboardSection('${s.id}')">Rename</button> <button class="btn sm danger" onclick="deleteDashboardSection('${s.id}')">Delete</button></div></div>`).join('')||'<div class="small">No custom sections yet.</div>'}</div><div class="section-title" style="margin-top:18px">Assign Projects to Sections</div><div class="section-project-list">${state.projects.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<div class="section-project-row"><div><b>${esc(p.name)}</b><div class="small">${esc(p.eventType||'')}</div></div><select onchange="assignDashboardSection('${p.id}',this.value)"><option value="">Unassigned</option>${sections.map(s=>`<option value="${s.id}" ${p.dashboardSectionId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>`).join('')}</div></div><div class="modal-foot"><button class="btn primary" onclick="closeModal();render()">Done</button></div>`)}
function addDashboardSection(){const input=document.getElementById('newSectionName'),name=(input?.value||'').trim();if(!name)return;state.dashboard=state.dashboard||{sections:[]};state.dashboard.sections.push({id:'sec-'+uid(),name});save();openSectionManager()}
function renameDashboardSection(id){const s=dashboardSections().find(x=>x.id===id);if(!s)return;const name=prompt('Section name',s.name);if(name&&name.trim()){s.name=name.trim();save();openSectionManager()}}
function moveDashboardSection(i,d){const a=dashboardSections(),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];save();openSectionManager()}
function deleteDashboardSection(id){const s=dashboardSections().find(x=>x.id===id);if(!s||!confirm(`Delete section "${s.name}"? Projects will become Unassigned.`))return;state.projects.forEach(p=>{if(p.dashboardSectionId===id)p.dashboardSectionId=''});state.dashboard.sections=state.dashboard.sections.filter(x=>x.id!==id);if(dashboardFilter.section===id)dashboardFilter.section='All';save();openSectionManager()}
function assignDashboardSection(projectId,sectionId){const p=project(projectId);if(p){p.dashboardSectionId=sectionId;save()}}
function updateProjectInline(id,field,value,el){const p=project(id);if(!p)return;const allowed=['code','name','eventType','format','owner','plannedStart','plannedEnd'];if(!allowed.includes(field))return;value=(value||'').trim();if((field==='code'||field==='name')&&!value){alert(field==='code'?'Project Code is required.':'Project Name is required.');if(el)el.value=p[field]||'';return}if(field==='plannedStart'&&p.plannedEnd&&value&&dateVal(value)>dateVal(p.plannedEnd)){alert('Plan Start cannot be later than Plan End.');if(el)el.value=p.plannedStart||'';return}if(field==='plannedEnd'&&p.plannedStart&&value&&dateVal(value)<dateVal(p.plannedStart)){alert('Plan End cannot be earlier than Plan Start.');if(el)el.value=p.plannedEnd||'';return}p[field]=value;save();if(el){el.dataset.saved='1';setTimeout(()=>delete el.dataset.saved,500)}}
function setProjectDashboardFlag(id,checked){const p=project(id);if(!p)return;p.showOnDashboard=!!checked;save();render()}
function filterProjectList(q){projectListSearch=(q||'').trim().toLowerCase();render()}
function projectListSortMeta(){const s=projectListSort;if(s==='eventTypeDesc')return['eventType','desc'];if(s==='eventTypeAsc')return['eventType','asc'];if(s==='projectDesc')return['project','desc'];if(s==='projectAsc')return['project','asc'];if(s==='formatDesc')return['format','desc'];if(s==='formatAsc')return['format','asc'];if(s==='ownerDesc')return['owner','desc'];if(s==='ownerAsc')return['owner','asc'];if(s==='planStartDesc')return['planStart','desc'];if(s==='planStartAsc')return['planStart','asc'];if(s==='planEndDesc')return['planEnd','desc'];if(s==='planEndAsc')return['planEnd','asc'];if(s==='liveDesc')return['live','desc'];if(s==='liveAsc')return['live','asc'];if(s==='statusDesc')return['status','desc'];if(s==='statusAsc')return['status','asc'];if(s==='dashboardDesc')return['dashboard','desc'];if(s==='dashboardAsc')return['dashboard','asc'];return['project','asc']}
function compareProjectList(a,b){const [key,dir]=projectListSortMeta();let c=0;if(key==='eventType')c=String(a.eventType||'').localeCompare(String(b.eventType||''));else if(key==='project')c=String(a.name||'').localeCompare(String(b.name||''));else if(key==='format')c=String(a.format||'').localeCompare(String(b.format||''));else if(key==='owner')c=String(a.owner||'').localeCompare(String(b.owner||''));else if(key==='planStart')c=dateVal(a.plannedStart)-dateVal(b.plannedStart);else if(key==='planEnd')c=dateVal(a.plannedEnd)-dateVal(b.plannedEnd);else if(key==='live')c=dateVal(projectLiveDate(a))-dateVal(projectLiveDate(b));else if(key==='status')c=String(projectStatus(a)||'').localeCompare(String(projectStatus(b)||''));else if(key==='dashboard')c=Number(a.showOnDashboard!==false)-Number(b.showOnDashboard!==false);if(c===0)c=String(a.name||'').localeCompare(String(b.name||''));return dir==='desc'?-c:c}
function setProjectListSortHeader(key){const [current,dir]=projectListSortMeta();const nextDir=current===key&&dir==='asc'?'desc':'asc';projectListSort=key+nextDir.charAt(0).toUpperCase()+nextDir.slice(1);render()}
function projectListSortIndicator(key){const [current,dir]=projectListSortMeta();return current===key?`<span class="sort-indicator">${dir==='asc'?'▲':'▼'}</span>`:'<span class="sort-indicator">↕</span>'}
function projectListHeader(label,key,cls=''){const [current]=projectListSortMeta();return`<th class="sortable ${current===key?'sorted':''} ${cls}" onclick="setProjectListSortHeader('${key}')">${label}${projectListSortIndicator(key)}</th>`}
function projectTable(ps){const q=projectListSearch;const rows=(ps||[]).filter(p=>!q||[p.code,p.name,p.eventType,p.format,p.owner,p.summary].some(v=>String(v||'').toLowerCase().includes(q))).sort(compareProjectList);if(!rows.length)return`<div class="empty">${q?'No project matches your search.':'No projects.'}</div>`;return`<div class="table-wrap"><table class="table project-list-table"><thead><tr>${projectListHeader('Event Type','eventType','col-event')}${projectListHeader('Project','project','col-project')}${projectListHeader('Format','format','col-format')}${projectListHeader('Owner','owner','col-owner')}${projectListHeader('Plan Start','planStart','col-date')}${projectListHeader('Plan End','planEnd','col-date')}${projectListHeader('Live Week','live','col-live')}${projectListHeader('Status','status','col-status')}${projectListHeader('Dashboard','dashboard','col-dashboard')}<th class="col-action">Action</th></tr></thead><tbody>${rows.map(p=>`<tr class="${p.showOnDashboard===false?'dashboard-hidden-row':''}"><td><input class="inline-edit" value="${esc(p.eventType||'')}" aria-label="Event Type for ${esc(p.name)}" onchange="updateProjectInline('${p.id}','eventType',this.value,this)"></td><td><div class="inline-project-cell"><input class="inline-edit inline-project-code" value="${esc(p.code||'')}" aria-label="Project Code" onchange="updateProjectInline('${p.id}','code',this.value,this)"><input class="inline-edit project-name" value="${esc(p.name||'')}" aria-label="Project Name" onchange="updateProjectInline('${p.id}','name',this.value,this)"></div><div class="project-progress-mini">Progress ${progress(p)}% (${p.progressMode==='reported'?'reported':'calc'}) · ${esc(p.criticality||'Normal')} · ${Number(p.capacityHours||0)}h · ${upcomingActivities(p,14).length} due in 14D${overdueSteps(p).length?` · <span class="danger-text">${overdueSteps(p).length} overdue</span>`:''}</div></td><td><input class="inline-edit" value="${esc(p.format||'')}" aria-label="Format" onchange="updateProjectInline('${p.id}','format',this.value,this)"></td><td><input class="inline-edit" value="${esc(p.owner||'')}" aria-label="Owner" onchange="updateProjectInline('${p.id}','owner',this.value,this)"></td><td><input class="inline-edit" type="date" value="${esc(p.plannedStart||'')}" aria-label="Plan Start" onchange="updateProjectInline('${p.id}','plannedStart',this.value,this)"></td><td><input class="inline-edit" type="date" value="${esc(p.plannedEnd||'')}" aria-label="Plan End" onchange="updateProjectInline('${p.id}','plannedEnd',this.value,this)"></td><td class="project-live-week" title="${esc(projectLiveDate(p))}">${esc(projectLiveWeek(p))}</td><td title="Status is derived from Detail Plan milestones">${statusPill(projectStatus(p))}</td><td><label class="dashboard-flag ${p.showOnDashboard===false?'hide':'show'}" title="Control whether this project appears on Dashboard"><input type="checkbox" ${p.showOnDashboard===false?'':'checked'} onchange="setProjectDashboardFlag('${p.id}',this.checked)"><span>${p.showOnDashboard===false?'Hide':'Show'}</span></label></td><td><div class="project-row-actions"><button class="btn sm primary" onclick="openDetail('${p.id}')">Detail Plan</button><button class="btn sm" onclick="openProjectModal('${p.id}')">More</button></div></td></tr>`).join('')}</tbody></table></div>`}
function renderProjects(){const visible=state.projects.filter(p=>p.showOnDashboard!==false).length;return`<div class="page"><div class="page-head"><div><h1>Project List</h1><div class="sub">Quick-edit core project information directly in the list. Dashboard Flag controls which projects appear on Dashboard · ${visible}/${state.projects.length} shown.</div></div><button class="btn primary" onclick="openProjectModal()">+ New Project</button></div><div class="card section"><div class="project-list-toolbar"><input class="quick-search" type="search" placeholder="Search project, code, event type, format or owner..." value="${esc(projectListSearch)}" oninput="projectListSearch=this.value.toLowerCase();const q=this.value;clearTimeout(window._projectSearchTimer);window._projectSearchTimer=setTimeout(()=>filterProjectList(q),180)"><span class="autosave-note"><i></i>Changes auto-save when you leave a field · click headers to sort</span></div>${projectTable(state.projects)}</div></div>`}
function openDetail(id){state.selectedProjectId=id;save();page='detail';render()}
function renderDetail(){const p=project();if(!p)return`<div class="page"><div class="empty">Create a project first.</div></div>`;const grouped={};(p.activities||[]).forEach(a=>{grouped[a.task]??={};grouped[a.task][a.subTask]??=[];grouped[a.task][a.subTask].push(a)});return `<div class="page"><div class="page-head"><div><h1>${esc(p.code)} · ${esc(p.name)}</h1><div class="sub">${esc(p.eventType)} · ${esc(p.division)} / ${esc(p.department)} · ${esc(p.format)}</div></div><div class="toolbar"><button class="btn" onclick="openProjectModal('${p.id}')">Edit Project</button><button class="btn primary" onclick="openActivityModal()">+ Add Activity</button></div></div><div class="summary-grid"><div class="mini"><span>Status</span><b>${statusPill(projectStatus(p))}</b></div><div class="mini"><span>Progress</span><b>${progress(p)}%</b></div><div class="mini"><span>Owner</span><b>${esc(p.owner)}</b></div><div class="mini"><span>Plan Start</span><b>${esc(p.plannedStart)}</b></div><div class="mini"><span>Plan End</span><b>${esc(p.plannedEnd)}</b></div><div class="mini"><span>Overdue Actions</span><b class="${overdueSteps(p).length?'danger-text':''}">${overdueSteps(p).length}</b></div><div class="mini"><span>Capacity</span><b>${Number(p.capacityHours||0)}h</b></div><div class="mini"><span>Criticality</span><b>${esc(p.criticality||'Normal')}</b></div></div><div class="card section"><div class="section-title" style="display:flex;align-items:center;gap:8px">Gantt Timeline <span class="small">Task → Sub Task → Key Milestone</span><span class="gantt-edit-hint"><i></i>Click = Edit · Drag = Move · Drag edge = Resize</span><span style="margin-left:auto"></span><span class="small">Group by</span><select onchange="detailGanttGroup=this.value;render()"><option value="milestone" ${detailGanttGroup==='milestone'?'selected':''}>Milestone</option><option value="task" ${detailGanttGroup==='task'?'selected':''}>Task</option><option value="taskSubTask" ${detailGanttGroup==='taskSubTask'?'selected':''}>Task → Sub Task</option></select><select onchange="ganttMode=this.value;render()"><option ${ganttMode==='Day'?'selected':''}>Day</option><option ${ganttMode==='Week'?'selected':''}>Week</option><option ${ganttMode==='Month'?'selected':''}>Month</option></select><button class="btn sm" onclick="ganttZoom=Math.max(25,ganttZoom-25);render()">−</button><span class="small">${ganttZoom}%</span><button class="btn sm" onclick="ganttZoom=Math.min(200,ganttZoom+25);render()">+</button></div>${renderGantt(p)}</div><div class="split" style="margin-top:14px"><div class="card section"><div class="section-title">Detail Plan Structure</div><div class="structure">${Object.entries(grouped).map(([task,subs])=>`<div class="task-card"><div class="task-head"><span>${esc(task)}</span><button class="btn sm" onclick="openActivityModal('',${esc(JSON.stringify(task))})">+ Milestone</button></div>${Object.entries(subs).map(([sub,items])=>`<div class="subtask"><div class="sub-head"><b>${esc(sub)}</b><span style="display:flex;align-items:center;gap:8px"><span class="small">${items.length} milestone(s)</span><button class="btn sm" onclick="openActivityModal('',${esc(JSON.stringify(task))},${esc(JSON.stringify(sub))})">+ Milestone</button></span></div>${items.sort((a,b)=>dateVal(a.plannedStart)-dateVal(b.plannedStart)).map(a=>renderActivity(p,a)).join('')}</div>`).join('')}</div>`).join('')||'<div class="empty">No activities.</div>'}</div></div><div><div class="card section"><div class="section-title">Presentation Notes</div><div class="weekly-update-box"><div class="ff"><label>Weekly Update / Current Focus</label><textarea onchange="updateProjectText('weeklyUpdate',this.value)">${esc(p.weeklyUpdate||'')}</textarea></div></div><div class="ff" style="margin-top:10px"><label>Project Summary</label><textarea onchange="updateProjectText('summary',this.value)">${esc(p.summary||'')}</textarea></div><div class="ff" style="margin-top:10px"><label>Risk / Issue</label><textarea onchange="updateProjectText('risk',this.value)">${esc(p.risk||'')}</textarea></div><div class="ff" style="margin-top:10px"><label>Decision / Support Needed</label><textarea onchange="updateProjectText('decision',this.value)">${esc(p.decision||'')}</textarea></div><div style="margin-top:12px"><button class="btn primary" onclick="startPresentation('${p.id}')">Present This Project</button></div></div><div class="card section" style="margin-top:14px"><div class="section-title">Upcoming 14 Days</div>${upcomingActivities(p,14).map(a=>`<div class="bullet"><span class="dot"></span><div><b>${esc(a.key)} · ${esc(a.label||ms(a.key).name)}</b><div class="small">Due ${esc(a.plannedEnd)} · ${STATUS_LABEL[a.status]}</div></div></div>`).join('')||'<div class="small">No milestone due.</div>'}</div></div></div></div>`}
function renderActivity(p,a){const m=ms(a.key);return `<div class="activity"><div class="code" style="background:${m.color};cursor:pointer" title="Click to edit milestone" onclick="openActivityModal('${a.id}')">${esc(a.key)}</div><div><b>${esc(a.label||m.name)}</b><div class="small">${esc(a.task)} → ${esc(a.subTask)}</div></div><div><b>${esc((a.responsibilities||[]).map(r=>r.pic||r.unit).join(', ')||'—')}</b><div class="small">${esc((a.responsibilities||[]).map(r=>r.unit).join(' / '))}</div></div><div>${esc(a.plannedStart)}</div><div>${esc(a.plannedEnd)}</div><div>${statusPill(a.status)}</div><div class="right"><button class="btn sm" onclick="openActivityModal('${a.id}')">Edit</button> <button class="btn sm danger" onclick="deleteActivity('${a.id}')">Delete</button></div></div><div class="next-steps"><div class="small"><b>Next Steps</b></div>${(a.nextSteps||[]).map((s,i)=>`<div class="next-row"><input value="${esc(s.text)}" onchange="updateStep('${a.id}','${s.id}','text',this.value)"><input type="date" value="${esc(s.due)}" onchange="updateStep('${a.id}','${s.id}','due',this.value)"><select onchange="updateStep('${a.id}','${s.id}','status',this.value)"><option value="NotStarted" ${s.status==='NotStarted'?'selected':''}>Not Started</option><option value="InProgress" ${s.status==='InProgress'?'selected':''}>In Progress</option><option value="Completed" ${s.status==='Completed'?'selected':''}>Completed</option></select><button class="btn sm danger" onclick="deleteStep('${a.id}','${s.id}')">×</button></div>`).join('')}<button class="btn sm" style="margin-top:7px" onclick="addStep('${a.id}')">+ Add Next Step</button></div>`}
function renderGantt(p){const acts=(p.activities||[]).slice().sort((a,b)=>dateVal(a.plannedStart)-dateVal(b.plannedStart));if(!acts.length)return'<div class="empty">No activities.</div>';const day=86400000;let min=Math.min(...acts.map(a=>dateVal(a.plannedStart))),max=Math.max(...acts.map(a=>dateVal(a.plannedEnd)));min-=3*day;max+=3*day;const zoom=ganttZoom/100;const cellDay=36*zoom,cellWeek=56*zoom,cellMonth=120*zoom;let width=1200,cell=cellDay,headerRows='',weekendHtml='',dateCells='',weekCells='',monthCells='',unit='day';
if(ganttMode==='Day'){const totalDays=Math.max(1,Math.round((max-min)/day)+1);width=Math.max(1200,totalDays*cellDay);cell=cellDay;for(let i=0;i<totalDays;i++){const dt=new Date(min+i*day);const left=i*cell;const isWeekend=[0,6].includes(dt.getDay());if(isWeekend)weekendHtml+=`<i class="gantt-weekend" style="left:${left}px;width:${cell}px"></i>`;dateCells+=`<div class="axis-date ${isWeekend?'weekend':''}" style="left:${left}px;width:${cell}px"><span>${String(dt.getDate()).padStart(2,'0')}</span></div>`;}let i=0;while(i<totalDays){const dt=new Date(min+i*day);const wk=isoWeek(dt);let j=i+1;while(j<totalDays){const d2=new Date(min+j*day);if(isoWeek(d2)!==wk)break;j++;}weekCells+=`<div class="axis-group" style="left:${i*cell}px;width:${(j-i)*cell}px">W${String(wk).padStart(2,'0')}</div>`;i=j;}i=0;while(i<totalDays){const dt=new Date(min+i*day);const key=dt.getFullYear()+'-'+dt.getMonth();let j=i+1;while(j<totalDays){const d2=new Date(min+j*day);if((d2.getFullYear()+'-'+d2.getMonth())!==key)break;j++;}monthCells+=`<div class="axis-group" style="left:${i*cell}px;width:${(j-i)*cell}px">${dt.toLocaleDateString('en',{month:'short',year:'numeric'})}</div>`;i=j;}headerRows=`<div class="axis-row months" style="width:${width}px">${monthCells}</div><div class="axis-row weeks" style="width:${width}px">${weekCells}</div><div class="axis-row dates" style="width:${width}px">${dateCells}</div>`;unit='day';}
else if(ganttMode==='Week'){const start=startOfWeekMs(min);const end=startOfWeekMs(max)+7*day;const totalWeeks=Math.max(1,Math.ceil((end-start)/(7*day)));width=Math.max(1200,totalWeeks*cellWeek);cell=cellWeek;for(let i=0;i<totalWeeks;i++){const dt=new Date(start+i*7*day);weekCells+=`<div class="axis-group" style="left:${i*cell}px;width:${cell}px">W${String(isoWeek(dt)).padStart(2,'0')}</div>`;}let i=0;while(i<totalWeeks){const dt=new Date(start+i*7*day+3*day);const key=dt.getFullYear()+'-'+dt.getMonth();let j=i+1;while(j<totalWeeks){const d2=new Date(start+j*7*day+3*day);if((d2.getFullYear()+'-'+d2.getMonth())!==key)break;j++;}monthCells+=`<div class="axis-group" style="left:${i*cell}px;width:${(j-i)*cell}px">${dt.toLocaleDateString('en',{month:'short',year:'numeric'})}</div>`;i=j;}headerRows=`<div class="axis-row months" style="width:${width}px">${monthCells}</div><div class="axis-row weeks" style="width:${width}px">${weekCells}</div>`;min=start;max=end-day;unit='week';}
else{const start=new Date(min);start.setDate(1);start.setHours(12,0,0,0);const end=new Date(max);end.setMonth(end.getMonth()+1,1);end.setHours(12,0,0,0);const months=[];const cursor=new Date(start);while(cursor<end){months.push(new Date(cursor));cursor.setMonth(cursor.getMonth()+1);}width=Math.max(1200,months.length*cellMonth);cell=cellMonth;monthCells=months.map((dt,i)=>`<div class="axis-group" style="left:${i*cell}px;width:${cell}px">${dt.toLocaleDateString('en',{month:'short',year:'numeric'})}</div>`).join('');headerRows=`<div class="axis-row months" style="width:${width}px">${monthCells}</div>`;min=start.getTime();max=end.getTime()-day;unit='month';}
const minDate=new Date(min);const todayMs=dateVal(dateOffset(0));let todayX=0;if(unit==='day')todayX=(todayMs-min)/day*cell;else if(unit==='week')todayX=(startOfWeekMs(todayMs)-min)/(7*day)*cell;else{const d=new Date(todayMs);todayX=((d.getFullYear()-minDate.getFullYear())*12+d.getMonth()-minDate.getMonth())*cell;}
const activityRow=a=>{let startX=0,w=cell;if(unit==='day'){startX=(dateVal(a.plannedStart)-min)/day*cell;w=Math.max(cell,(days(a.plannedStart,a.plannedEnd)+1)*cell);}else if(unit==='week'){startX=(startOfWeekMs(dateVal(a.plannedStart))-min)/(7*day)*cell;w=Math.max(cell,Math.ceil((dateVal(a.plannedEnd)-startOfWeekMs(dateVal(a.plannedStart))+day)/(7*day))*cell);}else{const ds=new Date(a.plannedStart),de=new Date(a.plannedEnd);const startMonth=((ds.getFullYear()-minDate.getFullYear())*12+ds.getMonth()-minDate.getMonth());const endMonth=((de.getFullYear()-minDate.getFullYear())*12+de.getMonth()-minDate.getMonth());startX=startMonth*cell;w=Math.max(cell,(endMonth-startMonth+1)*cell);}const m=ms(a.key);const label=`${a.key} - ${STATUS_LABEL[a.status]}`;return `<div class="gantt-row"><div class="gantt-label"><b>${esc(a.key)}</b> ${esc(a.label||m.name)}${a.isCriticalPath?'<span class="critical-mark">CRITICAL</span>':''}<div class="small">${esc(a.task)} / ${esc(a.subTask)}</div></div><div class="gantt-track" style="width:${width}px;--cell:${cell}px">${weekendHtml}${todayX>=0&&todayX<=width?`<i class="today" style="left:${todayX}px"></i>`:''}<div class="gantt-bar ${a.isCriticalPath?'critical':''}" data-activity-id="${esc(a.id)}" data-start="${esc(a.plannedStart)}" data-end="${esc(a.plannedEnd)}" data-unit="${unit}" data-cell="${cell}" title="Click to edit · Drag to move · Drag edges to resize\n${esc(a.plannedStart)} → ${esc(a.plannedEnd)}" style="left:${startX}px;width:${w}px;background:${m.color}"><span class="gantt-resize left" data-resize="start"></span><span class="gantt-drag-date">${esc(a.plannedStart)} → ${esc(a.plannedEnd)}</span><span class="gantt-bar-text">${esc(label)}</span><span class="gantt-resize right" data-resize="end"></span></div></div></div>`};
const groupRow=(label,items,type='task')=>{const dated=items.filter(a=>a.plannedStart&&a.plannedEnd);let startX=0,w=0;if(dated.length){if(unit==='day'){startX=(Math.min(...dated.map(a=>dateVal(a.plannedStart)))-min)/day*cell;w=Math.max(cell,(Math.max(...dated.map(a=>dateVal(a.plannedEnd)))-Math.min(...dated.map(a=>dateVal(a.plannedStart))))/day*cell+cell)}else if(unit==='week'){startX=(startOfWeekMs(Math.min(...dated.map(a=>dateVal(a.plannedStart))))-min)/(7*day)*cell;w=Math.max(cell,(Math.ceil((Math.max(...dated.map(a=>dateVal(a.plannedEnd)))-startOfWeekMs(Math.min(...dated.map(a=>dateVal(a.plannedStart))))+day)/(7*day)))*cell)}else{const ds=new Date(Math.min(...dated.map(a=>dateVal(a.plannedStart)))),de=new Date(Math.max(...dated.map(a=>dateVal(a.plannedEnd))));const sm=((ds.getFullYear()-minDate.getFullYear())*12+ds.getMonth()-minDate.getMonth()),em=((de.getFullYear()-minDate.getFullYear())*12+de.getMonth()-minDate.getMonth());startX=sm*cell;w=Math.max(cell,(em-sm+1)*cell)}}return `<div class="gantt-group-row"><div class="gantt-group-label ${type==='subtask'?'subtask':''}">${type==='subtask'?'↳':''}${esc(label)} <span class="gantt-group-count">${items.length}</span></div><div class="gantt-group-track" style="width:${width}px;--cell:${cell}px">${weekendHtml}${todayX>=0&&todayX<=width?`<i class="today" style="left:${todayX}px"></i>`:''}${dated.length?`<i class="gantt-group-summary" style="left:${startX}px;width:${w}px"></i>`:''}</div></div>`};
let rows='';if(detailGanttGroup==='milestone'){rows=acts.map(activityRow).join('')}else{const taskKeys=uniqueValues(acts.map(a=>a.task||'Unassigned Task'));rows=taskKeys.map(task=>{const taskActs=acts.filter(a=>(a.task||'Unassigned Task')===task).sort((a,b)=>dateVal(a.plannedStart)-dateVal(b.plannedStart));let out=groupRow(task,taskActs,'task');if(detailGanttGroup==='taskSubTask'){const subKeys=uniqueValues(taskActs.map(a=>a.subTask||'Unassigned Sub Task'));out+=subKeys.map(sub=>{const subActs=taskActs.filter(a=>(a.subTask||'Unassigned Sub Task')===sub).sort((a,b)=>dateVal(a.plannedStart)-dateVal(b.plannedStart));return groupRow(sub,subActs,'subtask')+subActs.map(activityRow).join('')}).join('')}else out+=taskActs.map(activityRow).join('');return out}).join('')}
return`<div class="gantt-wrap"><div class="gantt" style="width:${260+width}px"><div class="gantt-axis"><div class="gantt-left-head"><b>Activity</b></div><div class="axis-track" style="width:${width}px">${todayX>=0&&todayX<=width?`<div class="today-badge" style="left:${todayX}px">Today</div>`:''}${headerRows}</div></div>${rows}</div></div>`}
function formatDateMs(msv){const d=new Date(msv);d.setHours(12,0,0,0);return d.toISOString().slice(0,10)}
function addMonthsDate(dateStr,n){const d=new Date(dateVal(dateStr));const originalDay=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(originalDay,last));return formatDateMs(d.getTime())}
function recomputeProjectPlanDates(p){const dated=(p.activities||[]).filter(a=>a.plannedStart&&a.plannedEnd);if(!dated.length)return;p.plannedStart=dated.map(a=>a.plannedStart).sort()[0];p.plannedEnd=dated.map(a=>a.plannedEnd).sort().slice(-1)[0]}
function shiftActivityDates(a,mode,steps){if(!steps)return;const day=86400000;if(mode==='month'){a.plannedStart=addMonthsDate(a.plannedStart,steps);a.plannedEnd=addMonthsDate(a.plannedEnd,steps)}else{const mult=mode==='week'?7:1;a.plannedStart=formatDateMs(dateVal(a.plannedStart)+steps*mult*day);a.plannedEnd=formatDateMs(dateVal(a.plannedEnd)+steps*mult*day)}}
function resizeActivityDate(a,edge,mode,steps){if(!steps)return;const day=86400000,mult=mode==='week'?7:1;if(edge==='start'){const next=mode==='month'?addMonthsDate(a.plannedStart,steps):formatDateMs(dateVal(a.plannedStart)+steps*mult*day);if(dateVal(next)<=dateVal(a.plannedEnd))a.plannedStart=next}else{const next=mode==='month'?addMonthsDate(a.plannedEnd,steps):formatDateMs(dateVal(a.plannedEnd)+steps*mult*day);if(dateVal(next)>=dateVal(a.plannedStart))a.plannedEnd=next}}
function initGanttInteractions(){const bars=[...document.querySelectorAll('.gantt-bar[data-activity-id]')];bars.forEach(bar=>{bar.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;const p=project();const a=p?.activities?.find(x=>x.id===bar.dataset.activityId);if(!a)return;e.preventDefault();e.stopPropagation();const handle=e.target.closest('.gantt-resize');const action=handle?(handle.dataset.resize==='start'?'resize-start':'resize-end'):'move';const unit=bar.dataset.unit||'day';const cell=Math.max(1,Number(bar.dataset.cell)||36);const startX=e.clientX;const originalLeft=parseFloat(bar.style.left)||0;const originalWidth=parseFloat(bar.style.width)||cell;const startDate=a.plannedStart,endDate=a.plannedEnd;let lastSteps=0,moved=false;bar.classList.add('dragging');bar.setPointerCapture?.(e.pointerId);const tooltip=bar.querySelector('.gantt-drag-date');const stepPx=cell;const previewDates=steps=>{let s=startDate,en=endDate;if(action==='move'){if(unit==='month'){s=addMonthsDate(s,steps);en=addMonthsDate(en,steps)}else{const mult=unit==='week'?7:1,delta=steps*mult*86400000;s=formatDateMs(dateVal(s)+delta);en=formatDateMs(dateVal(en)+delta)}}else if(action==='resize-start'){if(unit==='month')s=addMonthsDate(s,steps);else s=formatDateMs(dateVal(s)+steps*(unit==='week'?7:1)*86400000);if(dateVal(s)>dateVal(en))s=en}else{if(unit==='month')en=addMonthsDate(en,steps);else en=formatDateMs(dateVal(en)+steps*(unit==='week'?7:1)*86400000);if(dateVal(en)<dateVal(s))en=s}return [s,en]};const onMove=ev=>{const dx=ev.clientX-startX;const steps=Math.round(dx/stepPx);if(Math.abs(dx)>4)moved=true;if(steps===lastSteps&&moved)return;lastSteps=steps;let left=originalLeft,width=originalWidth;if(action==='move')left=originalLeft+steps*stepPx;else if(action==='resize-start'){const maxStep=Math.floor((originalWidth-cell)/stepPx);const bounded=Math.min(steps,maxStep);lastSteps=bounded;left=originalLeft+bounded*stepPx;width=originalWidth-bounded*stepPx}else{const minStep=Math.ceil((cell-originalWidth)/stepPx);const bounded=Math.max(steps,minStep);lastSteps=bounded;width=originalWidth+bounded*stepPx}bar.style.left=left+'px';bar.style.width=Math.max(cell,width)+'px';const [s,en]=previewDates(lastSteps);if(tooltip)tooltip.textContent=s+' → '+en};const finish=ev=>{window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',cancel);bar.releasePointerCapture?.(e.pointerId);bar.classList.remove('dragging');if(!moved&&action==='move'){openActivityModal(a.id);return}if(!lastSteps){render();return}const live=project()?.activities?.find(x=>x.id===a.id);if(!live)return;if(action==='move')shiftActivityDates(live,unit,lastSteps);else resizeActivityDate(live,action==='resize-start'?'start':'end',unit,lastSteps);recomputeProjectPlanDates(project());save();render()};const cancel=()=>{window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',cancel);bar.classList.remove('dragging');render()};window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',finish,{once:true});window.addEventListener('pointercancel',cancel,{once:true})})})}
function updateProjectText(field,val){const p=project();p[field]=val;save()}
function addStep(activityId){const a=project().activities.find(x=>x.id===activityId);a.nextSteps??=[];a.nextSteps.push({id:uid(),text:'New action',due:dateOffset(7),status:'NotStarted'});save();render()}
function updateStep(activityId,stepId,field,val){const a=project().activities.find(x=>x.id===activityId);const s=(a.nextSteps||[]).find(x=>x.id===stepId);if(s){s[field]=val;save()}}
function deleteStep(activityId,stepId){const a=project().activities.find(x=>x.id===activityId);a.nextSteps=(a.nextSteps||[]).filter(x=>x.id!==stepId);save();render()}
function deleteActivity(id){if(!confirm('Delete this activity and its Next Steps?'))return;const p=project();p.activities=p.activities.filter(a=>a.id!==id);save();render()}
// removed legacy openProjectModal
function ff(label,id,value,type='text'){return`<div class="ff"><label>${label}</label><input id="${id}" type="${type}" value="${esc(value)}"></div>`}
// removed legacy saveProjectModal
function deleteProject(id){if(!confirm('Delete this project?'))return;state.projects=state.projects.filter(p=>p.id!==id);state.selectedProjectId=state.projects[0]?.id||'';save();closeModal();page='projects';render()}
// removed legacy openActivityModal
function responsibilityFields(list){return(list||[]).map((r,i)=>`<div class="form-grid" style="margin-bottom:8px"><div class="ff"><label>Responsible Unit</label><input value="${esc(r.unit)}" disabled></div><div class="ff"><label>PIC Name</label><input class="respPic" data-unit="${esc(r.unit)}" value="${esc(r.pic||'')}"></div></div>`).join('')||'<div class="small">No unit assigned in Key Milestone Master.</div>'}
function refreshResponsibilityFields(key){const units=ms(key).units;document.getElementById('respFields').innerHTML=responsibilityFields(units.map(u=>({unit:u,pic:''})))}
// removed legacy saveActivityModal
function v(id){return(document.getElementById(id)?.value||'').trim()}
function showModal(html){document.getElementById('modalCard').innerHTML=html;document.getElementById('modal').classList.remove('hidden')}
function closeModal(){document.getElementById('modal').classList.add('hidden')}
function startPresentation(id){presentProjectIds=[id];presentIndex=0;page='presentation';render()}
function renderPresentation(){if(!presentProjectIds.length)presentProjectIds=state.projects.map(p=>p.id);const p=project(presentProjectIds[presentIndex]||state.selectedProjectId);if(!p)return'<div class="page"><div class="empty">No project to present.</div></div>';const inprog=(p.activities||[]).filter(a=>['InProgress','AtRisk','Delayed','OnHold'].includes(a.status));const next=(p.activities||[]).flatMap(a=>(a.nextSteps||[]).filter(s=>s.status!=='Completed').map(s=>({a,s}))).sort((x,y)=>dateVal(x.s.due)-dateVal(y.s.due)).slice(0,5);const recent=completedRecent(p).slice(0,4);return`<div class="present-shell"><div class="present-controls" style="max-width:1500px;margin:0 auto 10px;display:flex;gap:8px;color:white;align-items:center"><button class="btn" onclick="presentIndex=Math.max(0,presentIndex-1);render()">← Previous</button><button class="btn" onclick="presentIndex=Math.min(presentProjectIds.length-1,presentIndex+1);render()">Next →</button><span>${presentIndex+1} / ${presentProjectIds.length}</span><span style="margin-left:auto"></span><button class="btn" onclick="window.print()">Print / PDF</button><button class="btn primary" onclick="document.documentElement.requestFullscreen?.()">Full Screen</button></div><section class="slide"><div class="slide-head"><div><div class="slide-title">${esc(p.name)}</div><div class="sub">${esc(p.code)} · ${esc(p.eventType)} · ${esc(p.division)} / ${esc(p.department)}</div></div><div>${statusPill(projectStatus(p))}</div></div><div class="slide-body"><div class="slide-left"><div class="metric-row"><div class="slide-metric"><span>Progress</span><b>${progress(p)}%</b></div><div class="slide-metric"><span>Owner</span><b style="font-size:14px">${esc(p.owner)}</b></div><div class="slide-metric"><span>Upcoming 14D</span><b>${upcomingActivities(p,14).length}</b></div><div class="slide-metric"><span>Overdue</span><b class="${overdueSteps(p).length?'danger-text':''}">${overdueSteps(p).length}</b></div></div><div class="slide-card"><h3>Weekly Update / Executive Summary</h3><div>${esc(p.weeklyUpdate||p.summary||'No update entered.')}</div></div><div class="slide-card" style="flex:1"><h3>Current Focus / In Progress</h3>${inprog.slice(0,6).map(a=>`<div class="bullet"><span class="dot" style="background:${ms(a.key).color}"></span><div><b>${esc(a.key)} · ${esc(a.label||ms(a.key).name)}</b> ${statusPill(a.status)}<div class="small">${esc(a.task)} → ${esc(a.subTask)} · ${esc(a.plannedStart)} → ${esc(a.plannedEnd)}</div></div></div>`).join('')||'<div class="small">No active milestone.</div>'}</div><div class="slide-card"><h3>Recently Completed</h3>${recent.map(a=>`<div class="bullet"><span class="dot" style="background:${ms(a.key).color}"></span><div><b>${esc(a.key)} · ${esc(a.label||ms(a.key).name)}</b><div class="small">Completed ${esc(a.actualEnd||a.plannedEnd)}</div></div></div>`).join('')||'<div class="small">No recent completion.</div>'}</div></div><div class="slide-right"><div class="slide-card"><h3>Next Steps</h3>${next.map(x=>`<div class="bullet"><span class="dot"></span><div><b>${esc(x.s.text)}</b><div class="small">${esc(x.a.key)} · Due ${esc(x.s.due)} · ${esc(x.s.status)}</div></div></div>`).join('')||'<div class="small">No open next steps.</div>'}</div><div class="slide-card"><h3>Risk / Issue</h3><div>${esc(p.risk||'No critical risk recorded.')}</div></div><div class="slide-card"><h3>Decision / Support Needed</h3><div>${esc(p.decision||'No decision required.')}</div></div><div class="slide-card" style="flex:1"><h3>Key Milestones</h3>${(p.activities||[]).slice().sort((a,b)=>dateVal(a.plannedEnd)-dateVal(b.plannedEnd)).slice(-7).map(a=>`<div style="display:grid;grid-template-columns:52px 1fr 80px;gap:8px;padding:6px 0;border-bottom:1px solid #edf1f5"><span class="code" style="background:${ms(a.key).color};padding:3px 5px">${esc(a.key)}</span><span>${esc(a.label||ms(a.key).name)}</span><span class="small">${esc(a.plannedEnd)}</span></div>`).join('')}</div></div></div><div class="slide-foot"><span>Range Operation Platform · Control Tower v2.0</span><span>Updated ${new Date().toLocaleString()}</span></div></section></div>`}
function renderMaster(){return`<div class="page"><div class="page-head"><div><h1>Master Data</h1><div class="sub">Maintain selectable values used by Detail Plan.</div></div></div><div class="master-grid"><div class="card master-list"><div class="section-title">Task Master <button class="btn sm primary" style="float:right" onclick="addMasterTask()">+</button></div>${state.masters.tasks.map((t,i)=>`<div class="master-item"><span>${i+1}. ${esc(t)}</span><span><button class="btn sm" onclick="moveItem('tasks',${i},-1)">↑</button> <button class="btn sm" onclick="moveItem('tasks',${i},1)">↓</button> <button class="btn sm danger" onclick="deleteMaster('tasks',${i})">×</button></span></div>`).join('')}</div><div class="card master-list"><div class="section-title">Key Milestone Master <button class="btn sm primary" style="float:right" onclick="addMilestoneMaster()">+</button></div>${state.masters.milestones.map((m,i)=>`<div class="master-item"><span><i class="color-dot" style="background:${m.color}"></i><b>${esc(m.key)}</b> · ${esc(m.name)}<div class="small">${esc(m.kind||'Milestone')}${m.isLiveDefault?' · Live driver':''} · ${esc(m.units.join(' / '))}</div></span><span><button class="btn sm" onclick="moveItem('milestones',${i},-1)">↑</button> <button class="btn sm" onclick="moveItem('milestones',${i},1)">↓</button> <button class="btn sm" onclick="editMilestoneMaster(${i})">Edit</button></span></div>`).join('')}</div><div class="card master-list"><div class="section-title">Responsible Unit Master <button class="btn sm primary" style="float:right" onclick="addUnitMaster()">+</button></div>${state.masters.units.map((u,i)=>`<div class="master-item"><span>${i+1}. ${esc(u)}</span><span><button class="btn sm" onclick="moveItem('units',${i},-1)">↑</button> <button class="btn sm" onclick="moveItem('units',${i},1)">↓</button> <button class="btn sm danger" onclick="deleteMaster('units',${i})">×</button></span></div>`).join('')}</div></div></div>`}
function moveItem(type,i,d){const a=state.masters[type],j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];save();render()}
function deleteMaster(type,i){if(!confirm('Delete this master item?'))return;state.masters[type].splice(i,1);save();render()}
function addMasterTask(){const x=prompt('Task name');if(x&&!state.masters.tasks.includes(x)){state.masters.tasks.push(x.trim());save();render()}}
function addUnitMaster(){const x=prompt('Responsible Unit name');if(x&&!state.masters.units.includes(x)){state.masters.units.push(x.trim());save();render()}}
function addMilestoneMaster(){showMilestoneModal(-1)}function editMilestoneMaster(i){showMilestoneModal(i)}
