function deleteMilestoneMaster(i){const key=state.masters.milestones[i].key;if(state.projects.some(p=>p.activities.some(a=>a.key===key)))return alert('This milestone is used by a project and cannot be deleted.');state.masters.milestones.splice(i,1);save();closeModal();render()}
function openProjectModal(id=''){const p=id?clone(project(id)):{id:uid(),code:'',name:'',eventType:'Major Range Change',division:'',department:'',owner:'',format:'Hyper',plannedStart:dateOffset(0),plannedEnd:dateOffset(30),summary:'',risk:'',decision:'',weeklyUpdate:'',dashboardSectionId:'',showOnDashboard:true,progressMode:'calculated',reportedProgress:null,capacityHours:0,criticality:'Normal',activities:[]};showModal(`<div class="modal-head"><h2>${id?'Edit':'New'} Project · Control Tower</h2><button class="btn sm" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid">${ff('Code','pmCode',p.code)}${ff('Project Name','pmName',p.name)}${ff('Event Type','pmEvent',p.eventType)}${ff('Division','pmDivision',p.division)}${ff('Department','pmDept',p.department)}${ff('Owner','pmOwner',p.owner)}${ff('Primary Format','pmFormat',p.format)}${ff('Planned Start','pmStart',p.plannedStart,'date')}${ff('Planned End','pmEnd',p.plannedEnd,'date')}<div class="ff"><label>Progress Mode</label><select id="pmProgressMode"><option value="calculated" ${p.progressMode!=='reported'?'selected':''}>Calculated (weighted activities)</option><option value="reported" ${p.progressMode==='reported'?'selected':''}>Reported by owner</option></select></div><div class="ff"><label>Reported Progress %</label><input id="pmReportedProgress" type="number" min="0" max="100" value="${p.reportedProgress===null||p.reportedProgress===undefined?'':esc(p.reportedProgress)}"></div><div class="ff"><label>Planned Capacity Hours</label><input id="pmCapacity" type="number" min="0" step="0.5" value="${esc(p.capacityHours||0)}"></div><div class="ff"><label>Criticality</label><select id="pmCriticality">${['Low','Normal','High','Critical'].map(x=>`<option ${p.criticality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="ff"><label>Custom Dashboard Section</label><select id="pmSection"><option value="">Unassigned</option>${dashboardSections().map(s=>`<option value="${s.id}" ${p.dashboardSectionId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="ff"><label>Dashboard Visibility</label><select id="pmDashboardFlag"><option value="show" ${p.showOnDashboard===false?'':'selected'}>Show on Dashboard</option><option value="hide" ${p.showOnDashboard===false?'selected':''}>Hide from Dashboard</option></select></div></div><div class="ff" style="margin-top:12px"><label>Weekly Update</label><textarea id="pmWeeklyUpdate" placeholder="Latest weekly update / current focus">${esc(p.weeklyUpdate||'')}</textarea></div></div><div class="modal-foot">${id?`<button class="btn danger" onclick="deleteProject('${id}')">Delete Project</button>`:''}<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveProjectModal('${id}')">Save</button></div>`)}
function saveProjectModal(id){const rp=v('pmReportedProgress');const vals={code:v('pmCode'),name:v('pmName'),eventType:v('pmEvent'),division:v('pmDivision'),department:v('pmDept'),owner:v('pmOwner'),format:v('pmFormat'),plannedStart:v('pmStart'),plannedEnd:v('pmEnd'),progressMode:v('pmProgressMode')||'calculated',reportedProgress:rp===''?null:Math.max(0,Math.min(100,Number(rp))),capacityHours:Math.max(0,Number(v('pmCapacity')||0)),criticality:v('pmCriticality')||'Normal',dashboardSectionId:v('pmSection'),showOnDashboard:v('pmDashboardFlag')!=='hide',weeklyUpdate:v('pmWeeklyUpdate')};if(!vals.name||!vals.code)return alert('Project Code and Project Name are required.');if(vals.plannedStart&&vals.plannedEnd&&dateVal(vals.plannedEnd)<dateVal(vals.plannedStart))return alert('Plan End cannot be earlier than Plan Start.');if(id){Object.assign(project(id),vals)}else{const p={id:uid(),...vals,summary:'',risk:'',decision:'',activities:[]};state.projects.push(p);state.selectedProjectId=p.id}save();closeModal();render()}
function openActivityModal(id='',prefillTask='',prefillSubTask=''){const p=project();const a=id?clone(p.activities.find(x=>x.id===id)):{id:uid(),task:prefillTask||state.masters.tasks[0]||'',subTask:prefillSubTask||'Main',key:state.masters.milestones[0]?.key||'',plannedStart:dateOffset(0),plannedEnd:dateOffset(7),actualStart:'',actualEnd:'',status:'Upcoming',activityType:'Activity',weight:1,isPrimaryLive:false,isCriticalPath:false,responsibilities:[],nextSteps:[]};const m=ms(a.key);if(!a.responsibilities.length)a.responsibilities=m.units.map(u=>({unit:u,pic:''}));showModal(`<div class="modal-head"><h2>${id?'Edit':'Add'} Plan Item</h2><button class="btn sm" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid"><div class="ff"><label>Task / Workstream</label><select id="amTask">${[...new Set([a.task,...state.masters.tasks].filter(Boolean))].map(t=>`<option ${t===a.task?'selected':''}>${esc(t)}</option>`).join('')}</select></div>${ff('Phase / Sub-Task','amSub',a.subTask)}<div class="ff"><label>Milestone / Activity</label><select id="amKey" onchange="refreshResponsibilityFields(this.value)">${state.masters.milestones.map(x=>`<option value="${esc(x.key)}" ${x.key===a.key?'selected':''}>${esc(x.key)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="ff"><label>Item Type</label><select id="amType"><option value="Activity" ${a.activityType!=='Milestone'?'selected':''}>Activity (duration)</option><option value="Milestone" ${a.activityType==='Milestone'?'selected':''}>Milestone (point/gate)</option></select></div><div class="ff"><label>Status</label><select id="amStatus">${STATUS.map(st=>`<option value="${st}" ${st===a.status?'selected':''}>${STATUS_LABEL[st]}</option>`).join('')}</select></div><div class="ff"><label>Weight</label><input id="amWeight" type="number" min="0.1" step="0.1" value="${esc(a.weight||1)}"></div>${ff('Planned Start','amStart',a.plannedStart,'date')}${ff('Planned End','amEnd',a.plannedEnd,'date')}${ff('Actual Start','amAStart',a.actualStart||'','date')}${ff('Actual End','amAEnd',a.actualEnd||'','date')}<div class="ff"><label>Primary Live Milestone</label><select id="amPrimaryLive"><option value="no" ${a.isPrimaryLive?'':'selected'}>No</option><option value="yes" ${a.isPrimaryLive?'selected':''}>Yes — drives Live Week</option></select></div><div class="ff"><label>Critical Path</label><select id="amCriticalPath"><option value="no" ${a.isCriticalPath?'':'selected'}>No</option><option value="yes" ${a.isCriticalPath?'selected':''}>Yes — critical path</option></select></div></div><div style="margin-top:14px"><div class="section-title">PIC / Responsible Persons</div><div id="respFields">${responsibilityFields(a.responsibilities)}</div></div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveActivityModal('${id}')">Save Item</button></div>`);window._editResp=clone(a.responsibilities)}
function saveActivityModal(id){const p=project();const responsibilities=[...document.querySelectorAll('.respPic')].map(x=>({unit:x.dataset.unit,pic:x.value.trim()}));const vals={task:v('amTask'),subTask:v('amSub'),key:v('amKey'),activityType:v('amType')||'Activity',weight:Math.max(.1,Number(v('amWeight')||1)),plannedStart:v('amStart'),plannedEnd:v('amEnd'),actualStart:v('amAStart'),actualEnd:v('amAEnd'),status:v('amStatus'),isPrimaryLive:v('amPrimaryLive')==='yes',isCriticalPath:v('amCriticalPath')==='yes',responsibilities};if(!vals.task||!vals.subTask||!vals.key||!vals.plannedStart||!vals.plannedEnd)return alert('Task, Phase/Sub-Task, milestone/activity and planned dates are required.');if(vals.activityType==='Milestone')vals.plannedEnd=vals.plannedStart;if(dateVal(vals.plannedEnd)<dateVal(vals.plannedStart))return alert('Planned End cannot be earlier than Planned Start.');if(vals.isPrimaryLive)(p.activities||[]).forEach(x=>{if(x.id!==id)x.isPrimaryLive=false});if(id)Object.assign(p.activities.find(x=>x.id===id),vals);else p.activities.push({id:uid(),...vals,nextSteps:[]});if(p.activities.length){p.plannedStart=p.activities.map(a=>a.plannedStart).filter(Boolean).sort()[0];p.plannedEnd=p.activities.map(a=>a.plannedEnd).filter(Boolean).sort().slice(-1)[0]}save();closeModal();render()}
function showMilestoneModal(i){const m=i>=0?clone(state.masters.milestones[i]):{key:'',name:'',color:COLORS[state.masters.milestones.length%COLORS.length],units:[],kind:'Milestone',isLiveDefault:false};showModal(`<div class="modal-head"><h2>${i>=0?'Edit':'Add'} Milestone Master</h2><button class="btn sm" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid">${ff('Code','mmKey',m.key)}${ff('Name','mmName',m.name)}<div class="ff"><label>Default Type</label><select id="mmKind"><option value="Milestone" ${m.kind!=='Activity'?'selected':''}>Milestone</option><option value="Activity" ${m.kind==='Activity'?'selected':''}>Activity</option></select></div><div class="ff"><label>Live Week Driver</label><select id="mmLive"><option value="no" ${m.isLiveDefault?'':'selected'}>No</option><option value="yes" ${m.isLiveDefault?'selected':''}>Yes</option></select></div><div class="ff"><label>Color</label><input id="mmColor" type="color" value="${esc(m.color)}"></div><div class="ff"><label>Responsible Units</label><select id="mmUnits" multiple size="5">${state.masters.units.map(u=>`<option ${m.units.includes(u)?'selected':''}>${esc(u)}</option>`).join('')}</select></div></div></div><div class="modal-foot">${i>=0?`<button class="btn danger" onclick="deleteMilestoneMaster(${i})">Delete</button>`:''}<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveMilestoneMaster(${i})">Save</button></div>`)}
function saveMilestoneMaster(i){const key=v('mmKey').toUpperCase(),name=v('mmName'),color=document.getElementById('mmColor').value,units=[...document.getElementById('mmUnits').selectedOptions].map(o=>o.value),kind=v('mmKind')||'Milestone',isLiveDefault=v('mmLive')==='yes';if(!key||!name)return alert('Code and Name required.');const m={key,name,color,units,kind,isLiveDefault};if(i>=0)state.masters.milestones[i]=m;else state.masters.milestones.push(m);save();closeModal();render()}
function exportJson(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='range-operation-platform-v2.0-backup-'+dateOffset(0)+'.json';a.click();URL.revokeObjectURL(a.href)}
function importJson(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x.projects||!x.masters)throw new Error('Invalid backup');state=migrateState(x);save();render();alert('Import completed.')}catch(err){alert(err.message)}};r.readAsText(f);e.target.value=''}
